-- =============================================================================
-- 507 — LE CAHIER D'EXERCICES DE 2DE (partie 9)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/2de/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 507 --niveau 2de --fichiers histoire-geo.n4,latin.n1,maths.n1 --suffixe 9 > supabase/contenu/507_exercices_2de_9.sql
--
-- 69 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   histoire-geo.n4         30 exercices · 10 chapitres
--   latin.n1                 9 exercices · 3 chapitres
--   maths.n1                30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('ad73844b-2c72-55cb-b3ad-beda315db5b3'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Deux géants émergents face à face","competence":"lire-tableau","situation":"Pour son exposé de géographie, Nina compare le Brésil et l’Inde, deux puissances émergentes du G20. Elle a rangé ses notes dans un tableau.","documents":[{"id":"compar","type":"tableau","titre":"Le Brésil et l’Inde en quatre critères","source":"Chiffres arrondis.","colonnes":["Critère","Brésil","Inde"],"lignes":[["Population","Environ 215 millions","Plus de 1,4 milliard"],["Urbanisation","Plus de 85 %","Encore majoritairement rurale"],["Moteur économique","Agriculture exportatrice","Services et numérique"],["Héritage pesant","Esclavage et question foncière","Système des castes"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui donne la population de l’Inde.","aide":"Cherche la ligne « Population », puis la colonne de l’Inde.","type":"zone","document":"compar","multiple":false},{"enonce":"Lequel de ces deux pays est le plus urbanisé ?","aide":"Regarde la ligne « Urbanisation » : l’un des deux pays est encore majoritairement rural.","type":"choix","options":[{"id":"a","texte":"L’Inde, dont la population est surtout urbaine"},{"id":"b","texte":"Les deux pays, avec la même part de citadins"},{"id":"c","texte":"Le tableau ne permet pas de comparer"},{"id":"d","texte":"Le Brésil, avec plus de 85 % de citadins"}],"multiple":false},{"enonce":"Touche la case qui décrit le moteur économique de l’Inde.","aide":"Ce moteur n’est ni l’agriculture ni l’industrie de masse.","type":"zone","document":"compar","multiple":false},{"enonce":"Sur 1 000 Brésiliens, combien vivent en ville au minimum ?","aide":"« Plus de 85 % » : calcule 85 % de 1 000.","type":"nombre","unite":"personnes"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"L’Inde compte **plus de 1,4 milliard** d’habitants : c’est le pays le plus peuplé du monde."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **Brésil** compte plus de 85 % de citadins ; l’Inde reste majoritairement rurale."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Le moteur de l’Inde, ce sont les **services et le numérique**, avec une industrialisation de masse faible."},{"cle":{"type":"nombre","valeur":850,"tolerance":0},"affichage":"850 personnes","explication":"85 % de 1 000 = 1 000 × 0,85 = **850** : au moins 850 Brésiliens sur 1 000 sont des citadins."}]$ex$::jsonb),
  ('ad73844b-2c72-55cb-b3ad-beda315db5b3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Même richesse moyenne, deux pays","competence":"lire-graphique","situation":"Karim lit deux fiches de pays imaginaires, A et B. Leur PIB par habitant est identique : il se demande si leurs habitants vivent pour autant de la même façon.","documents":[{"id":"indic","type":"tableau","titre":"Trois indicateurs","source":"Chiffres imaginés pour l’exercice.","colonnes":["Indicateur","Pays A","Pays B"],"lignes":[["PIB par habitant","12 000 $","12 000 $"],["IDH","0,79","0,72"],["Indice de Gini","0,29","0,58"]],"enteteLignes":true},{"id":"parts","type":"graphique","forme":"barres","titre":"Qui reçoit le revenu national ?","source":"Chiffres imaginés pour l’exercice.","categories":["20 % les plus pauvres","20 % les plus riches"],"series":[{"nom":"Pays A","valeurs":[9,36],"teinte":"violet"},{"nom":"Pays B","valeurs":[3,60],"teinte":"ambre"}],"axeY":{"titre":"Part du revenu national","unite":"en %","min":0,"max":70,"pas":10},"valeurs":true}],"questions":[{"enonce":"Touche la case qui montre le pays où les revenus sont répartis le moins également.","aide":"L’indice de Gini mesure l’inégalité des revenus : plus il est élevé, plus les écarts sont grands.","type":"zone","document":"indic","multiple":false},{"enonce":"Dans le pays B, combien de fois la part du revenu des 20 % les plus riches dépasse-t-elle celle des 20 % les plus pauvres ?","aide":"Divise la part des plus riches par celle des plus pauvres.","type":"nombre","unite":"fois"},{"enonce":"Pourquoi le PIB par habitant ne suffit-il pas pour comparer ces deux pays ?","aide":"Les deux pays ont le même PIB par habitant et pourtant des graphiques très différents.","type":"choix","options":[{"id":"a","texte":"Il mesure uniquement la santé et l’éducation des habitants"},{"id":"b","texte":"Il ne dit rien de la façon dont la richesse est partagée"},{"id":"c","texte":"Il est toujours inexact dans les pays émergents, où l’on compte mal"},{"id":"d","texte":"Il est calculé de la même façon dans tous les pays du monde"}],"multiple":false},{"enonce":"Complète la conclusion de Karim.","aide":"Un indicateur mesure la production, l’autre le partage.","type":"trous","segments":["Le PIB par habitant mesure la ",0," produite, mais c’est l’indice de ",1," qui mesure l’inégalité des revenus."],"banque":["richesse","Gini","espérance de vie","population"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Le pays B a un indice de Gini de **0,58**, contre 0,29 pour le pays A : ses revenus sont bien moins également répartis."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 fois","explication":"60 ÷ 3 = **20** : dans le pays B, les plus riches reçoivent vingt fois plus que les plus pauvres (contre 36 ÷ 9 = 4 fois dans le pays A)."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le PIB par habitant est une moyenne : il **ne dit rien du partage** de la richesse. Il faut y ajouter l’indice de Gini."},{"cle":{"type":"trous","trous":[["richesse"],["gini"]]},"affichage":"richesse · Gini","explication":"Le PIB par habitant mesure la **richesse** produite ; l’indice de **Gini** mesure l’inégalité de sa répartition."}]$ex$::jsonb),
  ('ad73844b-2c72-55cb-b3ad-beda315db5b3'::uuid, 3, 3, 15, 50, 3,
   $ex${"titre":"Joana à São Paulo, Sunita à Delhi","competence":"analyser-document","situation":"Deux femmes de 34 et 29 ans, l’une au Brésil, l’autre en Inde, racontent leur quotidien. En les lisant, tu vas distinguer ce que les deux pays partagent et ce qui les sépare.","documents":[{"id":"joana","type":"texte","genre":"recit","titre":"Portrait de Joana, São Paulo (Brésil)","source":"Portrait imaginé pour l’exercice.","blocs":["Joana a 34 ans. Elle vit dans une favela de São Paulo, à plus d’une heure de bus du quartier fermé où elle fait le ménage quatre jours par semaine.","Elle travaille dans le secteur informel : ni contrat, ni cotisation, ni protection sociale. Depuis quelques années, une aide versée par l’État lui permet de garder ses enfants à l’école."]},{"id":"sunita","type":"texte","genre":"recit","titre":"Portrait de Sunita, Delhi (Inde)","source":"Portrait imaginé pour l’exercice.","blocs":["Sunita a 29 ans. Née dans un village du Bihar, un État pauvre, elle a rejoint Delhi avec son mari. Elle vend des légumes sur un trottoir, sans autorisation ni protection : c’est aussi du travail informel. Le couple vit dans un bidonville.","Sa famille appartient à une caste défavorisée : cet héritage a longtemps fermé à ses parents l’accès à certains métiers."]}],"questions":[{"enonce":"Touche le mot qui désigne une inégalité liée à la naissance, que l’on retrouve en Inde.","aide":"Cherche dans le second paragraphe : c’est un héritage familial, pas un choix.","type":"zone","document":"sunita","multiple":false},{"enonce":"Range chaque trait selon le ou les pays qu’il décrit.","aide":"Les points communs figurent dans le dernier tableau du cours : bidonvilles, informel, croissance irrégulière.","type":"categories","categories":[{"id":"c0","texte":"Brésil"},{"id":"c1","texte":"Inde"},{"id":"c2","texte":"Les deux"}],"items":[{"id":"i0","texte":"Un Sudeste riche face à un Nordeste pauvre"},{"id":"i1","texte":"Un Kerala avancé face à un Bihar en retard"},{"id":"i2","texte":"Des favelas à côté de quartiers fermés, dans une même ville"},{"id":"i3","texte":"Des castes qui pèsent sur l’avenir"},{"id":"i4","texte":"Un secteur informel énorme"},{"id":"i5","texte":"Des bidonvilles dans les mégapoles"},{"id":"i6","texte":"Une croissance forte mais irrégulière"}]},{"enonce":"Que montrent ensemble les deux portraits ?","aide":"Relève ce que Joana et Sunita ont en commun dans leur travail.","type":"choix","options":[{"id":"a","texte":"Le développement avance, mais une part de la population reste hors de la protection sociale"},{"id":"b","texte":"Le développement a supprimé le travail informel dans les deux pays émergents"},{"id":"c","texte":"La croissance forte a fait disparaître les bidonvilles des grandes villes"},{"id":"d","texte":"Les inégalités ne concernent que les États les plus pauvres de chaque pays"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m48"]},"explication":"La **caste** se transmet à la naissance : en Inde, l’inégalité se lit aussi dans la naissance, ce qui n’a pas d’équivalent au Brésil."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c2","i5":"c2","i6":"c2"}},"explication":"Spécifiques au **Brésil** : les contrastes sociaux et spatiaux (favelas, Sudeste/Nordeste). Spécifiques à l’**Inde** : castes et écart Kerala/Bihar. Communs aux **deux** : bidonvilles, informel, croissance irrégulière."},{"cle":{"type":"choix","ids":["a"]},"explication":"Joana et Sunita travaillent toutes deux dans l’**informel**, sans protection : « le développement y avance, l’écart y demeure »."}]$ex$::jsonb),
  ('1923e92a-6b02-5285-88c6-adb89805bcbd'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le Japon en quatre repères","competence":"lire-tableau","situation":"Hana prépare une fiche sur le Japon, « laboratoire mondial du vieillissement ». Elle a relevé quatre chiffres clés.","documents":[{"id":"reperes","type":"tableau","titre":"Les repères démographiques du Japon","source":"Chiffres arrondis.","colonnes":["Repère","Valeur"],"lignes":[["Population","Environ 124 millions, en baisse depuis 2010 environ"],["Part des 65 ans et plus","Près de 29 %"],["Espérance de vie","Plus de 84 ans"],["Indice de fécondité","Environ 1,3 enfant par femme"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui donne l’espérance de vie au Japon.","aide":"Cherche la ligne qui parle de la durée de la vie.","type":"zone","document":"reperes","multiple":false},{"enonce":"Environ combien de Japonais sur 100 ont moins de 65 ans ?","aide":"Si 29 personnes sur 100 ont 65 ans ou plus, combien restent ?","type":"nombre","unite":"personnes"},{"enonce":"Pour que la population se renouvelle sans migration, il faut environ 2,1 enfants par femme. Que dit alors la fécondité du tableau ?","aide":"Compare 1,3 et 2,1.","type":"choix","options":[{"id":"a","texte":"Chaque génération est moins nombreuse que la précédente"},{"id":"b","texte":"La fécondité n’a aucun effet sur la population"},{"id":"c","texte":"La population se renouvelle exactement à l’identique"},{"id":"d","texte":"Chaque génération est plus nombreuse que la précédente"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c1"]},"explication":"L’espérance de vie dépasse **84 ans** : elle est exceptionnelle."},{"cle":{"type":"nombre","valeur":71,"tolerance":1},"affichage":"71 personnes","explication":"100 − 29 = **71** : environ 71 Japonais sur 100 ont moins de 65 ans."},{"cle":{"type":"choix","ids":["a"]},"explication":"Avec **1,3 enfant par femme**, très en dessous de 2,1, chaque génération est moins nombreuse : la population baisse."}]$ex$::jsonb),
  ('1923e92a-6b02-5285-88c6-adb89805bcbd'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Haruka et l’école qui a fermé","competence":"lire-graphique","situation":"Haruka a 16 ans et vit dans un village de montagne japonais. Son récit s’appuie sur une évolution que le graphique ci-dessous permet de mesurer.","documents":[{"id":"vieux","type":"graphique","forme":"barres","titre":"Les 65 ans et plus dans la population du Japon","source":"Chiffres arrondis, au pourcent près.","categories":["1960","1980","2000","2020"],"series":[{"nom":"65 ans et plus","valeurs":[6,9,17,29],"teinte":"violet"}],"axeY":{"titre":"Part de la population","unite":"en %","min":0,"max":35,"pas":5},"axeX":{"titre":"Année"}},{"id":"haruka","type":"texte","genre":"recit","titre":"Le village de Haruka","source":"Récit imaginé pour l’exercice.","blocs":["Dans mon village de montagne, l’école a fermé il y a deux ans, faute d’élèves. Je prends maintenant un car chaque matin pour rejoindre la ville voisine.","Beaucoup de maisons sont vides : mes cousins sont partis travailler à Tokyo. Il ne reste surtout que des grands-parents."]}],"questions":[{"enonce":"Combien de points de plus représente la part des 65 ans et plus en 2020 par rapport à 2000 ?","aide":"Lis la hauteur des deux dernières barres et fais la différence.","type":"nombre","unite":"points"},{"enonce":"Touche la date à partir de laquelle plus d’un Japonais sur quatre a 65 ans ou plus.","aide":"Un Japonais sur quatre correspond à 25 % : cherche la première barre qui dépasse ce niveau.","type":"zone","document":"vieux","multiple":false},{"enonce":"Touche le mot qui montre que le village se vide de ses habitants.","aide":"Cherche l’adjectif qui décrit les maisons dans le second paragraphe.","type":"zone","document":"haruka","multiple":false},{"enonce":"Range chaque fait parmi les causes ou les conséquences du vieillissement japonais.","aide":"Une cause explique la faible natalité ; une conséquence est ce que le vieillissement produit ensuite.","type":"categories","categories":[{"id":"c0","texte":"Cause"},{"id":"c1","texte":"Conséquence"}],"items":[{"id":"i0","texte":"La difficulté à concilier travail et famille"},{"id":"i1","texte":"Une pénurie de main-d’œuvre dans les soins"},{"id":"i2","texte":"Des villages fantômes"},{"id":"i3","texte":"Le coût du logement"},{"id":"i4","texte":"Une immigration longtemps très faible"},{"id":"i5","texte":"La fermeture d’écoles"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 points","explication":"29 − 17 = **12 points** : le vieillissement s’accélère."},{"cle":{"type":"zone","ids":["k3"]},"explication":"Seule la barre de **2020** (29 %) dépasse 25 % ; en 2000, la part n’atteint que 17 %."},{"cle":{"type":"zone","ids":["m33"]},"explication":"Les maisons **vides** illustrent les « villages fantômes » : les jeunes partent vers Tokyo, les campagnes se vident."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0","i5":"c1"}},"explication":"Logement cher, difficulté de concilier travail et famille, immigration faible : ce sont des **causes**. Écoles fermées, villages fantômes, pénurie de main-d’œuvre : des **conséquences**."}]$ex$::jsonb),
  ('1923e92a-6b02-5285-88c6-adb89805bcbd'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un pays qui cherche des réponses","competence":"analyser-document","situation":"Ichiro, 72 ans, travaille encore dans un entrepôt près d’Osaka. Son quotidien illustre les réponses que le Japon invente face à son vieillissement.","documents":[{"id":"reponses","type":"tableau","titre":"Les réponses du Japon","source":"D’après le cours.","colonnes":["Réponse","État"],"lignes":[["Robotique et automatisation","Développées, notamment dans les soins"],["Emploi des seniors","Souvent au-delà de 70 ans"],["Travail des femmes","Encouragé"],["Ouverture aux travailleurs étrangers","Prudente"],["Crèches et aides à la garde","En place"],["Revitalisation rurale","Engagée"]],"enteteLignes":true},{"id":"ichiro","type":"texte","genre":"article","titre":"Une journée dans l’entrepôt","source":"Reportage imaginé pour l’exercice.","blocs":["Ichiro, 72 ans, travaille quatre jours par semaine dans un entrepôt de logistique. Un robot porte les colis les plus lourds, il surveille les écrans.","Sa fille, qui travaille aussi, a obtenu une place en crèche pour son petit-fils."]}],"questions":[{"enonce":"Touche le mot qui illustre une réponse technique à la pénurie de main-d’œuvre.","aide":"Cherche ce qui remplace un effort physique dans l’entrepôt.","type":"zone","document":"ichiro","multiple":false},{"enonce":"Associe chaque réponse du tableau au problème qu’elle vise.","aide":"Pour chaque réponse, demande-toi quelle conséquence du vieillissement elle cherche à corriger.","type":"association","gauche":[{"id":"g0","texte":"Les robots dans les soins"},{"id":"g1","texte":"L’emploi des seniors au-delà de 70 ans"},{"id":"g2","texte":"Les crèches et les aides à la garde"},{"id":"g3","texte":"La revitalisation rurale"}],"droite":[{"id":"d0","texte":"Des villages qui se vident"},{"id":"d1","texte":"Des enfants qui ne naissent pas assez"},{"id":"d2","texte":"Des soignants qui manquent"},{"id":"d3","texte":"Des retraites qui coûtent cher"}]},{"enonce":"Touche la case qui montre la prudence du Japon face à l’arrivée de travailleurs étrangers.","aide":"Un mot du tableau résume l’attitude du pays sur cette ligne.","type":"zone","document":"reponses","multiple":false},{"enonce":"Le Japon compte environ 124 millions d’habitants, dont près de 29 % ont 65 ans ou plus. Combien de personnes de 65 ans et plus cela représente-t-il, en millions (arrondi à l’unité) ?","aide":"Calcule 29 % de 124.","type":"nombre","unite":"millions"},{"enonce":"Que peut-on conclure de l’ensemble de ces réponses ?","aide":"Reviens à la conclusion du cours sur ces réponses.","type":"choix","options":[{"id":"a","texte":"Aucune n’a inversé la tendance au vieillissement à ce jour"},{"id":"b","texte":"Le recours massif à l’immigration a inversé la tendance"},{"id":"c","texte":"La robotique a rajeuni la population du pays"},{"id":"d","texte":"Les politiques familiales ont rétabli la natalité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"Le **robot** porte les charges : la robotique et l’automatisation compensent le manque de bras."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"Robots : **manque de soignants**. Seniors au travail : **retraites** moins lourdes. Crèches : **natalité**. Revitalisation rurale : **villages qui se vident**."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"L’ouverture aux travailleurs étrangers est **prudente** : le Japon n’a pas massivement recours à l’immigration."},{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36 millions","explication":"124 × 0,29 = 35,96 ; arrondi à l’unité : **36 millions** de personnes."},{"cle":{"type":"choix","ids":["a"]},"explication":"Toutes ces mesures **n’ont pas inversé la tendance** : elles atténuent les effets du vieillissement sans le faire reculer."}]$ex$::jsonb),
  ('112922bd-10ff-540c-8d02-3c9072661973'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une population qui change d’allure","competence":"lire-tableau","situation":"Léo prépare un exposé sur la population française : environ 68 millions d’habitants, qui croissent encore lentement. Il a noté l’évolution de quatre indicateurs.","documents":[{"id":"mouvement","type":"tableau","titre":"Le mouvement d’ensemble","source":"D’après le cours ; chiffres arrondis.","colonnes":["Indicateur","Évolution"],"lignes":[["Fécondité","Longtemps la plus élevée d’Europe, descendue autour de 1,6 enfant par femme"],["Accroissement naturel","Il se réduit fortement"],["Solde migratoire","Il devient le principal moteur de la croissance"],["Plus de 65 ans","Plus de 21 %, et en hausse"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui nomme le principal moteur de la croissance de la population française.","aide":"Il ne s’agit ni des naissances ni des décès.","type":"zone","document":"mouvement","multiple":false},{"enonce":"Environ combien de personnes de plus de 65 ans compte la France, en prenant 21 % de 68 millions (arrondi au million) ?","aide":"Calcule 68 × 0,21.","type":"nombre","unite":"millions"},{"enonce":"Que dit le tableau de la fécondité française ?","aide":"Relis la première ligne : « longtemps » annonce un changement.","type":"choix","options":[{"id":"a","texte":"Elle a toujours été la plus faible d’Europe"},{"id":"b","texte":"Elle est restée stable depuis plusieurs décennies"},{"id":"c","texte":"Elle a baissé : elle était la plus élevée d’Europe"},{"id":"d","texte":"Elle a nettement progressé depuis quelques années"}],"multiple":false}]}$ex$::jsonb,
