  ('112922bd-10ff-540c-8d02-3c9072661973'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Où la France gagne et perd des habitants","competence":"lire-carte","situation":"Maëlys compare quatre villes de France pour comprendre pourquoi certains territoires attirent et d’autres se vident. La carte indique la diagonale des faibles densités.","documents":[{"id":"carte","type":"carte","titre":"Quatre villes et la diagonale des faibles densités","source":"Tracé schématique de la diagonale ; villes repérées pour l’exercice.","fond":"france","fleuves":false,"aires":[{"id":"z5","contour":[[5.2,49.6],[6.2,48.8],[5,47.4],[4,46.2],[3.5,44.8],[2.2,43.7],[0.6,43.2],[-0.4,43.4],[-0.2,44.2],[1,44.8],[1.6,45.9],[2,47],[3.2,48],[4,49.2]],"teinte":"ambre","motif":"clair","surTerre":true,"etiquette":"Faibles densités","etiquetteA":[5,47.3]}],"lieux":[{"id":"z1","lieu":"la-rochelle","symbole":"lettre","lettre":"A"},{"id":"z2","lieu":"montpellier","symbole":"lettre","lettre":"B"},{"id":"z3","lieu":"aurillac","symbole":"lettre","lettre":"C"},{"id":"z4","lieu":"gueret","symbole":"lettre","lettre":"D"}]}],"questions":[{"enonce":"Touche la diagonale des faibles densités.","aide":"C’est la bande qui va du Nord-Est au Massif central, puis au Sud-Ouest.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche les deux villes situées sur un littoral qui gagne des habitants.","aide":"Les littoraux atlantique et méditerranéen attirent la population.","type":"zone","document":"carte","multiple":true},{"enonce":"Touche les deux villes situées dans la diagonale des faibles densités.","aide":"Ce sont les deux villes de l’intérieur, dans la bande dessinée sur la carte.","type":"zone","document":"carte","multiple":true},{"enonce":"Quel phénomène étend les villes bien au-delà de leurs limites administratives ?","aide":"Le mot contient « autour de la ville ».","type":"choix","options":[{"id":"a","texte":"La littoralisation"},{"id":"b","texte":"La désindustrialisation"},{"id":"c","texte":"La périurbanisation"},{"id":"d","texte":"La métropolisation"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"La **diagonale des faibles densités** est une bande peu peuplée qui s’étire du Nord-Est au Massif central et au Sud-Ouest."},{"cle":{"type":"zone","ids":["z1","z2"]},"explication":"La Rochelle (littoral **atlantique**) et Montpellier (littoral **méditerranéen**) appartiennent aux territoires qui gagnent des habitants."},{"cle":{"type":"zone","ids":["z3","z4"]},"explication":"Aurillac (Cantal) et Guéret (Creuse) sont dans la **diagonale** : territoires peu denses, qui perdent des habitants."},{"cle":{"type":"choix","ids":["c"]},"explication":"La **périurbanisation** étend l’habitat et les activités au-delà des limites de la ville, loin des centres."}]$ex$::jsonb),
  ('112922bd-10ff-540c-8d02-3c9072661973'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Quatre territoires, quatre dispositifs","competence":"analyser-document","situation":"Une chargée de mission en aménagement doit choisir quel dispositif de l’État convient à chaque territoire. Elle part d’un graphique sur la fécondité et de quatre situations observées.","documents":[{"id":"fec","type":"graphique","forme":"courbe","titre":"Fécondité en France","source":"Chiffres arrondis à 0,1 enfant par femme.","categories":["2010","2015","2020","2024"],"series":[{"nom":"Enfants par femme","valeurs":[2,2,1.8,1.6],"teinte":"turquoise"}],"axeY":{"titre":"Fécondité","unite":"enfants par femme","min":1,"max":2.2,"pas":0.2},"axeX":{"titre":"Année"}},{"id":"cas","type":"texte","genre":"article","titre":"Quatre situations","source":"Texte écrit pour l’exercice ; communes et villes imaginaires.","blocs":["Dans la commune de Saint-Aubin, plus aucun guichet pour les papiers administratifs : la caisse d’allocations est à 40 km.","Dans un quartier de grande ville, le chômage est bien plus élevé qu’ailleurs dans l’agglomération et les logements sont dégradés.","Au centre de Valombre, ville moyenne, les vitrines vides se multiplient.","Dans plusieurs villages de montagne, les jeunes partent faute d’emplois et les écoles ferment. Le dernier médecin a pris sa retraite : le village est devenu un désert médical."]}],"questions":[{"enonce":"De combien la fécondité a-t-elle baissé entre 2010 et 2024 ?","aide":"Lis la valeur de 2010 et celle de 2024 sur la courbe.","type":"nombre","unite":"enfant par femme"},{"enonce":"Ce graphique suffit-il pour dire que la population française diminue ?","aide":"La fécondité n’est qu’un des moteurs de la population : rappelle-toi lequel est devenu le principal.","type":"choix","options":[{"id":"a","texte":"Oui : la France perd des habitants chaque année depuis 2010"},{"id":"b","texte":"Non : la fécondité française est restée stable depuis 2010"},{"id":"c","texte":"Oui : une fécondité en baisse fait toujours diminuer la population"},{"id":"d","texte":"Non : la fécondité baisse, mais le solde migratoire soutient encore la croissance"}],"multiple":false},{"enonce":"Touche l’expression qui désigne un territoire où l’accès aux soins est difficile.","aide":"Elle se trouve dans le dernier paragraphe, après le départ du médecin.","type":"zone","document":"cas","multiple":true},{"enonce":"Associe chaque situation au dispositif de l’État qui lui correspond.","aide":"Chaque dispositif cible un type de territoire : quartiers, services publics, villes moyennes, campagnes.","type":"association","gauche":[{"id":"g0","texte":"Un quartier cumulant chômage et logements dégradés"},{"id":"g1","texte":"Une commune sans guichet pour ses démarches"},{"id":"g2","texte":"Un centre de ville moyenne aux vitrines vides"},{"id":"g3","texte":"Des campagnes en déprise aux écoles qui ferment"}],"droite":[{"id":"d0","texte":"Action cœur de ville"},{"id":"d1","texte":"Les Maisons France Services"},{"id":"d2","texte":"Les zones de revitalisation rurale"},{"id":"d3","texte":"La politique de la ville"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0.4,"tolerance":0.05},"affichage":"0,4 enfant par femme","explication":"2,0 − 1,6 = **0,4 enfant par femme** de moins en quatorze ans."},{"cle":{"type":"choix","ids":["d"]},"explication":"La courbe baisse, mais la population croît encore, grâce au **solde migratoire** : la baisse de la fécondité ne dit pas tout."},{"cle":{"type":"zone","ids":["m80","m81"]},"explication":"Un **désert médical** est un territoire où l’accès aux soins est difficile, faute de médecins proches."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"Quartier en difficulté : **politique de la ville**. Accès aux services publics : **Maisons France Services**. Ville moyenne : **Action cœur de ville**. Campagnes en déprise : **zones de revitalisation rurale**."}]$ex$::jsonb),
  ('a0e2ce8a-947b-5ae8-b6cf-1685a6e997c5'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre parcours, quatre mots","competence":"analyser-texte","situation":"Une association d’aide aux exilés présente quatre parcours à des lycéens. Pour les comprendre, il faut employer chaque mot de la migration à bon escient.","documents":[{"id":"parcours","type":"texte","genre":"recit","titre":"Quatre parcours","source":"Portraits imaginés pour l’exercice.","blocs":["Karim a fui les combats qui ont détruit sa ville. Il vit dans un camp, à 80 km de chez lui, à l’intérieur de son pays.","Leïla a quitté son pays pour échapper à des persécutions. Elle a déposé un dossier dans le pays d’accueil et attend la décision.","Joseph, ingénieur, est parti travailler à Montréal pour un meilleur salaire.","Amina a fui la guerre. Le pays qui l’accueille lui a reconnu le statut de réfugiée, défini par la convention de Genève de 1951."]}],"questions":[{"enonce":"Touche le mot qui montre que Karim n’a pas quitté son pays.","aide":"Cherche, dans la première phrase, où se trouve le camp de Karim.","type":"zone","document":"parcours","multiple":false},{"enonce":"Associe chaque personne au terme qui la désigne.","aide":"Demande-toi à chaque fois : a-t-elle franchi une frontière ? Attend-elle une décision ou l’a-t-elle déjà obtenue ?","type":"association","gauche":[{"id":"g0","texte":"Karim"},{"id":"g1","texte":"Leïla"},{"id":"g2","texte":"Joseph"},{"id":"g3","texte":"Amina"}],"droite":[{"id":"d0","texte":"Déplacé interne"},{"id":"d1","texte":"Réfugiée"},{"id":"d2","texte":"Demandeur d’asile"},{"id":"d3","texte":"Migrant économique"}]},{"enonce":"Pourquoi Karim n’est-il pas un réfugié ?","aide":"Le statut de réfugié concerne une personne qui a quitté son pays.","type":"choix","options":[{"id":"a","texte":"Il n’a subi aucune violence dans sa ville"},{"id":"b","texte":"Il a refusé de déposer une demande d’asile"},{"id":"c","texte":"Il n’a pas franchi de frontière internationale"},{"id":"d","texte":"Il est parti uniquement pour un meilleur salaire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23"]},"explication":"Karim vit à l’**intérieur** de son pays : il n’a franchi aucune frontière internationale."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"Karim : **déplacé interne**. Leïla attend la décision : **demandeur d’asile**. Joseph part pour un salaire : **migrant économique**. Amina a obtenu le statut : **réfugiée**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Un **déplacé interne** reste dans son pays : sans frontière franchie, il n’est pas réfugié au sens de la convention de Genève."}]$ex$::jsonb),
  ('a0e2ce8a-947b-5ae8-b6cf-1685a6e997c5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Des flux qui ne vont pas tous vers le Nord","competence":"lire-carte","situation":"Sarah prépare une affiche sur les migrations. Elle a tracé quatre flèches, qui relient des villes de pays d’origine et de destination, pour illustrer des flux réels. Toutes ne traversent pas la planète.","documents":[{"id":"flux","type":"carte","titre":"Quatre exemples de flux migratoires","source":"Schéma illustratif : les flèches relient des villes, elles ne tracent pas des itinéraires.","fond":"monde","cadrage":[-105,-40,40,56],"lieux":[{"id":"z1","lieu":"mexico","symbole":"point","nom":"Mexico"},{"id":"z2","lieu":"chicago","symbole":"point","nom":"Chicago"},{"id":"z3","lieu":"lagos","symbole":"point","nom":"Lagos"},{"id":"z4","lieu":"londres","symbole":"point","nom":"Londres"},{"id":"z5","lieu":"kinshasa","symbole":"point","nom":"Kinshasa"},{"id":"z6","lieu":"johannesburg","symbole":"point","nom":"Johannesburg"},{"id":"z7","lieu":"lima","symbole":"point","nom":"Lima"},{"id":"z8","lieu":"santiago","symbole":"point","nom":"Santiago"}],"traits":[{"id":"z9","points":["mexico","chicago"],"style":"fleche","teinte":"violet","epaisseur":2},{"id":"z10","points":["lagos","londres"],"style":"fleche","teinte":"violet","epaisseur":2},{"id":"z11","points":["kinshasa","johannesburg"],"style":"fleche","teinte":"violet","epaisseur":2},{"id":"z12","points":["lima","santiago"],"style":"fleche","teinte":"violet","epaisseur":2}]}],"questions":[{"enonce":"Touche les deux flèches qui restent à l’intérieur de la même région du monde (flux Sud-Sud).","aide":"Pour chacune, regarde si le départ et l’arrivée sont sur le même continent.","type":"zone","document":"flux","multiple":true},{"enonce":"Touche la flèche qui va de l’Afrique de l’Ouest vers l’Europe.","aide":"Repère Lagos, sur le golfe de Guinée, puis une ville européenne.","type":"zone","document":"flux","multiple":false},{"enonce":"Deux flèches sur quatre restent dans la même région du monde. Que dit le cours des migrations internationales ?","aide":"Les flux Sud-Sud sont plus nombreux que les flux Sud-Nord.","type":"choix","options":[{"id":"a","texte":"Les migrants les plus pauvres sont ceux qui vont le plus loin"},{"id":"b","texte":"Les migrations Sud-Sud sont aujourd’hui très rares et récentes"},{"id":"c","texte":"La plupart des migrants quittent le Sud pour s’installer au Nord"},{"id":"d","texte":"Environ un migrant sur deux se déplace dans sa propre région du monde"}],"multiple":false},{"enonce":"Range chaque effet : pour qui est-il un apport ou un coût principal ?","aide":"Le cours classe les effets en trois colonnes : départ, arrivée, migrant.","type":"categories","categories":[{"id":"c0","texte":"Pays de départ"},{"id":"c1","texte":"Pays d’arrivée"},{"id":"c2","texte":"Migrant"}],"items":[{"id":"i0","texte":"Des remises massives"},{"id":"i1","texte":"Une mobilité sociale possible"},{"id":"i2","texte":"Discrimination et précarité fréquentes"},{"id":"i3","texte":"Un rajeunissement et des cotisations"},{"id":"i4","texte":"Des débats politiques sur l’intégration"},{"id":"i5","texte":"La fuite des cerveaux"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z11","z12"]},"explication":"Kinshasa → Johannesburg reste en **Afrique**, Lima → Santiago en **Amérique du Sud** : ce sont des flux Sud-Sud, plus nombreux que les flux Sud-Nord."},{"cle":{"type":"zone","ids":["z10"]},"explication":"La flèche **Lagos → Londres** relie l’Afrique de l’Ouest à l’Europe : c’est un flux Sud-Nord."},{"cle":{"type":"choix","ids":["d"]},"explication":"Un migrant sur deux reste dans sa propre région : les flux **Sud-Sud** dépassent les flux Sud-Nord. Partir loin coûte cher."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c2","i3":"c1","i4":"c1","i5":"c0"}},"explication":"**Départ** : remises, fuite des cerveaux. **Arrivée** : rajeunissement, cotisations, débats sur l’intégration. **Migrant** : mobilité sociale possible, discrimination et précarité."}]$ex$::jsonb),
  ('a0e2ce8a-947b-5ae8-b6cf-1685a6e997c5'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La lettre de Youssef","competence":"analyser-document","situation":"Youssef, ingénieur installé à Lyon, écrit à sa sœur restée dans leur village. Sa lettre et un tableau d’effets te permettent de mesurer ce que la migration apporte… et coûte.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre de Youssef à sa sœur Salma","source":"Lettre écrite pour l’exercice.","blocs":["Ma chère Salma, je suis arrivé à Lyon il y a trois ans. Chaque mois, je vous envoie 250 euros ; avec ces envois, le village a pu réparer le toit du dispensaire.","Mais le dispensaire n’a plus de pharmacien et deux infirmières sont aussi parties à l’étranger. Je me demande parfois si j’aurais dû rester."]},{"id":"effets","type":"tableau","titre":"Les effets de la migration","source":"D’après le cours.","colonnes":["Pour qui","L’apport","Le coût"],"lignes":[["Pays de départ","Des remises massives, parfois supérieures à l’aide publique au développement","La fuite des cerveaux"],["Pays d’arrivée","Main-d’œuvre, rajeunissement, cotisations","Des débats politiques sur l’intégration"],["Migrant","Une mobilité sociale possible","Discrimination et précarité fréquentes"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux mots qui montrent le départ de personnes qualifiées du village.","aide":"Cherche les deux métiers de la santé dont parle Youssef dans le second paragraphe.","type":"zone","document":"lettre","multiple":true},{"enonce":"Touche la case qui décrit l’apport que représentent, pour le village, les 250 euros envoyés chaque mois.","aide":"L’argent envoyé par les migrants à leur famille porte un nom : cherche-le dans la colonne « L’apport ».","type":"zone","document":"effets","multiple":false},{"enonce":"Combien d’euros Youssef envoie-t-il à son village en une année ?","aide":"Il envoie 250 euros par mois, pendant 12 mois.","type":"nombre","unite":"euros"},{"enonce":"Que dit le tableau du départ de Youssef pour son pays d’origine ?","aide":"Lis la ligne « Pays de départ » : elle a deux colonnes.","type":"choix","options":[{"id":"a","texte":"Il apporte des remises mais prive le pays de personnes qualifiées"},{"id":"b","texte":"Il prive le pays de qualifiés sans lui apporter aucune ressource"},{"id":"c","texte":"Il apporte uniquement des bénéfices, sans aucun coût pour le pays"},{"id":"d","texte":"Il n’a aucun effet, car les migrants restent dans leur pays"}],"multiple":false}]}$ex$::jsonb,
