2","texte":"Les garde-côtes italiens"}],"droite":[{"id":"d0","texte":"Il secourt les passagers en mer"},{"id":"d1","texte":"Ils contrôlent et désignent le port de débarquement"},{"id":"d2","texte":"Ils organisent la traversée et exploitent les migrants"}]}]}$ex$::jsonb,
