  ('f837d9fe-6056-5ec1-bb02-8fdac417942b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Au Cap, la pluie tombe l’hiver","competence":"lire-graphique","situation":"Le Cap, sur la façade méditerranéenne de l’Afrique du Sud, a connu en 2018 une crise majeure de l’eau. Le diagramme du climat de la ville aide à comprendre pourquoi l’eau y est fragile.","documents":[{"id":"climat","type":"graphique","forme":"climat","titre":"Le climat du Cap (Afrique du Sud)","source":"Moyennes mensuelles arrondies, ordres de grandeur.","categories":["J","F","M","A","M","J","J","A","S","O","N","D"],"series":[{"nom":"Températures","valeurs":[21,21,20,18,15,13,13,13,14,17,18,20]},{"nom":"Précipitations","valeurs":[15,17,20,41,69,93,82,77,40,30,20,14]}]},{"id":"crise","type":"texte","genre":"article","titre":"Une ville au bord du « jour zéro »","source":"Texte écrit pour l’exercice, d’après le cours.","blocs":["En 2018, Le Cap a connu une crise majeure de l’eau : après des années de sécheresse, les barrages étaient presque vides.","Les autorités ont compté à rebours les jours avant le « jour zéro », où l’eau courante aurait pu être coupée."]}],"questions":[{"enonce":"Touche le mois le plus arrosé au Cap.","aide":"Cherche la plus haute barre de précipitations.","type":"zone","document":"climat","multiple":false},{"enonce":"Combien de mois reçoivent moins de 25 mm de précipitations ?","aide":"Compte les barres inférieures à 25 mm, de novembre à mars.","type":"nombre","unite":"mois"},{"enonce":"Pourquoi un tel climat rend-il l’approvisionnement en eau fragile ?","aide":"Regarde les mois d’été : la pluie y est presque absente.","type":"choix","options":[{"id":"a","texte":"Les températures baissent trop pour que l’eau reste liquide"},{"id":"b","texte":"L’été est très sec alors que la ville a besoin d’eau toute l’année"},{"id":"c","texte":"Il pleut de la même façon chaque mois, sans réserve possible"},{"id":"d","texte":"La pluie tombe en été, quand les barrages sont déjà pleins"}],"multiple":false},{"enonce":"Touche le mot qui explique pourquoi les barrages étaient presque vides.","aide":"Cherche, dans la première phrase, l’événement climatique qui a duré plusieurs années.","type":"zone","document":"crise","multiple":false}]}$ex$::jsonb,
