   $ex${"titre":"D’où viennent les migrants de Johannesburg ?","competence":"analyser-document","situation":"Une association de Johannesburg a interrogé des migrants installés dans la métropole. Son enquête, imaginée ici, éclaire une réalité que le cours résume : l’Afrique du Sud attire, mais elle inquiète aussi.","documents":[{"id":"origines","type":"graphique","forme":"barres","titre":"Pays d’origine des migrants interrogés","source":"Chiffres imaginés pour l’exercice.","categories":["Zimbabwe","Mozambique","Lesotho","Malawi","Autres"],"series":[{"nom":"Part des migrants","valeurs":[40,25,15,10,10],"teinte":"turquoise"}],"axeY":{"titre":"Part des migrants interrogés","unite":"en %","min":0,"max":50,"pas":10}},{"id":"temoignage","type":"texte","genre":"article","titre":"Un quartier de Johannesburg","source":"Texte écrit pour l’exercice.","blocs":["Dans un quartier de Johannesburg, des commerçants venus des pays voisins tiennent de petits magasins. Ils font vivre leur famille et fournissent des services à leurs clients.","En 2008 et en 2015, des violences xénophobes ont visé des étrangers, dans un contexte de concurrence pour l’emploi."]}],"questions":[{"enonce":"Touche le pays d’origine le plus fréquent parmi les migrants interrogés.","aide":"Cherche la barre la plus haute.","type":"zone","document":"origines","multiple":false},{"enonce":"Quelle part des migrants interrogés vient du Zimbabwe ou du Mozambique ?","aide":"Additionne les deux premières barres.","type":"nombre","unite":"%"},{"enonce":"Touche le mot qui désigne les violences dirigées contre des étrangers.","aide":"C’est un adjectif du second paragraphe.","type":"zone","document":"temoignage","multiple":false},{"enonce":"Quelle phrase résume le mieux les deux documents ?","aide":"Un document parle d’origines, l’autre de ce que l’accueil produit.","type":"choix","options":[{"id":"a","texte":"L’Afrique du Sud attire les migrants de la région, et cela ne suscite aucune tension"},{"id":"b","texte":"Les migrants de la région viennent tous d’un seul pays voisin"},{"id":"c","texte":"L’Afrique du Sud attire les migrants de la région, mais leur présence suscite des tensions"},{"id":"d","texte":"Les migrants quittent l’Afrique du Sud, qui n’offre ni emploi ni commerce"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Le **Zimbabwe** (40 %) est le premier pays d’origine, devant le Mozambique."},{"cle":{"type":"nombre","valeur":65,"tolerance":0},"affichage":"65 %","explication":"40 + 25 = **65 %** : les deux pays sont les premières sources de migrants, comme le dit le cours."},{"cle":{"type":"zone","ids":["m34"]},"explication":"Les violences **xénophobes** de 2008 et 2015 ont révélé une tension sociale liée à la concurrence pour l’emploi."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’Afrique du Sud est un **pôle d’attraction** régional, mais l’arrivée des migrants alimente aussi des tensions : « terre promise » et territoire où l’on redoute celui qui arrive."}]$ex$::jsonb),
  ('2d1756e1-21f4-5d4b-9059-10e1605c5e9c'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Quatre voyageurs, quatre mobilités","competence":"se-reperer-temps","situation":"Mpho, Joaquim, Sophie et Nomsa traversent les frontières d’Afrique australe pour des raisons très différentes. Une frise replace dans le temps ce qui a façonné ces mobilités.","documents":[{"id":"frise","type":"frise","titre":"Quelques repères autour de Johannesburg","source":"Dates du cours et de l’histoire de la région.","debut":1880,"fin":2020,"pas":20,"evenements":[{"id":"z1","date":1886,"nom":"Ruée vers l’or"},{"id":"z2","date":1948,"nom":"Début de l’apartheid"},{"id":"z3","date":1994,"nom":"Élection de Mandela"},{"id":"z4","date":2008,"nom":"Violences xénophobes"}]},{"id":"voyageurs","type":"texte","genre":"article","titre":"Quatre voyageurs","source":"Portraits imaginés pour l’exercice.","blocs":["Mpho prépare un diplôme d’ingénieure dans une université sud-africaine : elle a quitté son pays pour étudier.","Joaquim vend des produits au marché, le long d’un corridor : chaque semaine, il passe la frontière sans déclarer ses marchandises.","Sophie, touriste européenne, passe une semaine de safari dans un parc national du nord de la région.","Nomsa travaille à Johannesburg et envoie chaque mois de l’argent à sa mère restée au Lesotho."]}],"questions":[{"enonce":"Range ces événements du plus ancien au plus récent.","aide":"Lis les dates sur la frise, de gauche à droite.","type":"ordre","items":[{"id":"a","texte":"Le début de l’apartheid"},{"id":"b","texte":"Les violences xénophobes de 2008"},{"id":"c","texte":"L’élection de Mandela"},{"id":"d","texte":"La ruée vers l’or"}]},{"enonce":"Combien d’années séparent la ruée vers l’or de l’élection de Nelson Mandela ?","aide":"Soustrais la date de la ruée vers l’or à celle de l’élection.","type":"nombre","unite":"ans"},{"enonce":"Touche l’événement qui a révélé des tensions sociales liées à la concurrence pour l’emploi.","aide":"Il s’agit de violences contre des étrangers.","type":"zone","document":"frise","multiple":false},{"enonce":"Associe chaque voyageur à sa forme de mobilité.","aide":"Pour chacun, cherche ce qui motive son déplacement.","type":"association","gauche":[{"id":"g0","texte":"Mpho"},{"id":"g1","texte":"Joaquim"},{"id":"g2","texte":"Sophie"},{"id":"g3","texte":"Nomsa"}],"droite":[{"id":"d0","texte":"Tourisme international"},{"id":"d1","texte":"Remises de la diaspora"},{"id":"d2","texte":"Mobilité étudiante"},{"id":"d3","texte":"Commerce transfrontalier informel"}]},{"enonce":"Pourquoi la ruée vers l’or de la fin du XIXe siècle explique-t-elle encore des mobilités actuelles ?","aide":"Pense à ce que la frise dit de Johannesburg et au rôle des mines dans le cours.","type":"choix","options":[{"id":"a","texte":"Elle a fait de Johannesburg un pôle d’attraction qui draine la main-d’œuvre régionale"},{"id":"b","texte":"Elle a fixé toute la population régionale dans les campagnes depuis lors"},{"id":"c","texte":"Elle a supprimé le commerce transfrontalier le long des grands corridors"},{"id":"d","texte":"Elle a interdit l’arrivée de travailleurs étrangers dans les villes minières"}],"multiple":false}]}$ex$::jsonb,
