  ('ebcfe609-313e-5a5b-99c2-5283b2d070c1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Rosa, dominus, templum : cinq familles de noms","competence":"manier-langue","situation":"Hugo ouvre son manuel de latin : six noms, un par exemple de chaque déclinaison. Avant de traduire, il doit apprendre à les reconnaître à leurs formes.","documents":[{"id":"tab","type":"tableau","titre":"Les cinq déclinaisons","colonnes":["Déclinaison","Nominatif","Génitif","Genre"],"lignes":[["1re","rosa","rosae","féminin"],["2e","dominus","domini","masculin"],["2e","templum","templi","neutre"],["3e","consul","consulis","masculin"],["4e","manus","manus","féminin"],["5e","res","rei","féminin"]],"source":"Tableau des exemples du cours"}],"questions":[{"enonce":"Touche le génitif de « rosa ».","aide":"Le génitif est dans la troisième colonne.","type":"zone","document":"tab","multiple":false},{"enonce":"Touche le seul génitif qui se termine par « -is ».","aide":"La 3e déclinaison se reconnaît à son génitif.","type":"zone","document":"tab","multiple":false},{"enonce":"Associe chaque déclinaison à la finale de son génitif singulier.","aide":"Les exemples sont dans le tableau.","type":"association","gauche":[{"id":"g0","texte":"1re déclinaison"},{"id":"g1","texte":"2e déclinaison"},{"id":"g2","texte":"3e déclinaison"},{"id":"g3","texte":"4e déclinaison"},{"id":"g4","texte":"5e déclinaison"}],"droite":[{"id":"d0","texte":"-ei"},{"id":"d1","texte":"-ae"},{"id":"d2","texte":"-is"},{"id":"d3","texte":"-us"},{"id":"d4","texte":"-i"}]}]}$ex$::jsonb,
