  ('ebcfe609-313e-5a5b-99c2-5283b2d070c1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le maître, l’esclave et la rose","competence":"comprendre-langue","situation":"Hugo traduit trois phrases très courtes. Le professeur lui a interdit de les lire dans l’ordre des mots : il doit d’abord repérer les cas.","documents":[{"id":"phrases","type":"texte","genre":"recit","titre":"Trois phrases à analyser","auteur":"Phrases écrites pour l’exercice","blocs":["Dominus servum vocat.","Servus domini templum videt.","Marcus tabulam servo dat."],"source":"Vocabulaire : dominus = le maître ; servus = l’esclave ; vocat = il appelle ; videt = il voit ; templum = le temple ; tabula = la tablette ; dat = il donne."}],"questions":[{"enonce":"Dans la phrase 1, touche le sujet du verbe.","aide":"Le sujet est au nominatif.","type":"zone","document":"phrases","multiple":false},{"enonce":"Dans la phrase 2, touche le complément du nom (le génitif).","aide":"Il répond à « de qui ? ».","type":"zone","document":"phrases","multiple":false},{"enonce":"Associe chaque forme de la phrase 1 et de la phrase 2 à son cas.","aide":"Pense à la fonction : sujet, COD, complément du nom.","type":"association","gauche":[{"id":"g0","texte":"dominus"},{"id":"g1","texte":"servum"},{"id":"g2","texte":"domini"}],"droite":[{"id":"d0","texte":"accusatif"},{"id":"d1","texte":"génitif"},{"id":"d2","texte":"nominatif"}]},{"enonce":"Quelle est la traduction de la phrase 3 ?","aide":"Cherche le sujet, le COD, puis le datif qui suit le verbe « donner ».","type":"choix","options":[{"id":"a","texte":"Marcus donne la tablette à l’esclave."},{"id":"b","texte":"L’esclave donne la tablette à Marcus."},{"id":"c","texte":"Marcus donne la tablette de l’esclave."},{"id":"d","texte":"Marcus donne l’esclave à la tablette."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0"]},"explication":"**Dominus** est le sujet : c’est la forme du nominatif, qui s’accorde avec le verbe *vocat*."},{"cle":{"type":"zone","ids":["m4"]},"explication":"**Domini** est au génitif : c’est le maître à qui appartient le temple (« le temple du maître »)."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Dominus** est le sujet (nominatif), **servum** le COD (accusatif) et **domini** un complément du nom (génitif)."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Marcus donne la tablette à l’esclave** : Marcus est le sujet, *tabulam* le COD (accusatif) et *servo* le datif, complément d’attribution du verbe *dat*."}]$ex$::jsonb),
  ('ebcfe609-313e-5a5b-99c2-5283b2d070c1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Cave canem : traduire en commençant par le verbe","competence":"analyser-texte","situation":"Hugo doit traduire trois phrases latines : une inscription d’une maison de Pompéi, une formule célèbre et une phrase écrite pour s’entraîner. Il suit la méthode du cours.","documents":[{"id":"phrases","type":"texte","genre":"source","titre":"Trois phrases à traduire","blocs":["Cave canem.","Panem et circenses.","Consul portam urbis aperit."],"source":"Phrase 1 : inscription de Pompéi. Phrase 2 : Juvénal, Satires, X. Phrase 3 : écrite pour l’exercice (aperit = il ouvre)."},{"id":"decl","type":"tableau","titre":"La 3e déclinaison : consul, consulis","colonnes":["Cas","Singulier","Pluriel"],"lignes":[["Nominatif","consul","consules"],["Accusatif","consulem","consules"],["Génitif","consulis","consulum"],["Datif","consuli","consulibus"],["Ablatif","consule","consulibus"]]}],"questions":[{"enonce":"Dans la phrase 3, touche le verbe : c’est lui qu’on repère en premier.","aide":"Il est placé en fin de phrase et se termine par -t.","type":"zone","document":"phrases","multiple":false},{"enonce":"Dans la phrase 3, touche le sujet.","aide":"Le sujet est au nominatif et s’accorde avec le verbe.","type":"zone","document":"phrases","multiple":false},{"enonce":"Dans le tableau, touche les deux formes du pluriel qui se confondent (nominatif et accusatif).","aide":"Cherche deux cases identiques dans la colonne du pluriel.","type":"zone","document":"decl","multiple":true},{"enonce":"Dans la phrase 1, quel est le cas de « canem » ?","aide":"Compare avec la forme « consulem » du tableau.","type":"choix","options":[{"id":"a","texte":"accusatif"},{"id":"b","texte":"nominatif"},{"id":"c","texte":"génitif"},{"id":"d","texte":"datif"}],"multiple":false},{"enonce":"Remets dans l’ordre les étapes de l’analyse de la phrase 3.","aide":"Le verbe d’abord, la rédaction en dernier.","type":"ordre","items":[{"id":"a","texte":"Rédiger : le consul ouvre la porte de la ville"},{"id":"b","texte":"Repérer le verbe : aperit"},{"id":"c","texte":"Placer le complément du nom au génitif : urbis"},{"id":"d","texte":"Trouver le COD à l’accusatif : portam"},{"id":"e","texte":"Trouver le sujet au nominatif : consul"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"**Aperit** est le verbe conjugué (« il ouvre ») : on commence toujours par lui."},{"cle":{"type":"zone","ids":["m5"]},"explication":"**Consul** est le sujet : c’est le nominatif, qui s’accorde avec *aperit*."},{"cle":{"type":"zone","ids":["r0c2","r1c2"]},"explication":"Au pluriel, le nominatif et l’accusatif sont tous deux en **consules** : il faudra que le sens ou le verbe tranche."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Canem** est à l’accusatif : sa finale -em est celle de l’accusatif singulier de la 3e déclinaison. Il est le COD de *cave*."},{"cle":{"type":"ordre","ids":["b","e","d","c","a"]},"explication":"La méthode est : **verbe**, **nominatif**, **accusatif**, compléments, puis seulement la rédaction en français."}]$ex$::jsonb),
  ('17840e75-285b-5a4f-8200-93ae94fce9fa'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Je dis que Marcus vient","competence":"manier-langue","situation":"Clara découvre une construction que le français n’a pas : après un verbe de parole ou de vue, le latin met le sujet à l’accusatif et le verbe à l’infinitif.","documents":[{"id":"phrases","type":"texte","genre":"recit","titre":"Trois phrases","auteur":"Phrases écrites pour l’exercice","blocs":["Dico Marcum venire.","Puella dicit servum ridere.","Video puellam ridere."],"source":"Vocabulaire : dico, dicit = je dis, elle dit ; video = je vois ; venire = venir ; ridere = rire."}],"questions":[{"enonce":"Dans la phrase 1, touche le verbe de parole qui introduit la proposition infinitive.","aide":"Il signifie « je dis ».","type":"zone","document":"phrases","multiple":false},{"enonce":"Dans la phrase 1, touche le sujet de « venire ».","aide":"Dans une infinitive, le sujet est à l’accusatif.","type":"zone","document":"phrases","multiple":false},{"enonce":"Quelle est la traduction de la phrase 1 ?","aide":"Le latin n’emploie pas « que » : c’est l’infinitive qui joue ce rôle.","type":"choix","options":[{"id":"a","texte":"Marcus dit que je viens."},{"id":"b","texte":"Je dis que Marcus vient."},{"id":"c","texte":"Je dis à Marcus de venir."},{"id":"d","texte":"Je dis Marcus venir."}],"multiple":false},{"enonce":"Complète la traduction de la phrase 2.","aide":"Le verbe de parole est dicit ; ridere est à l’infinitif.","type":"trous","segments":["Puella dicit servum ridere : la jeune fille ",0," que l’esclave ",1,"."],"banque":["rient","dit","voit","rit"]}]}$ex$::jsonb,
