  ('17840e75-285b-5a4f-8200-93ae94fce9fa'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Après la prise de la ville","competence":"comprendre-langue","situation":"Clara lit deux phrases du récit d’une guerre. Chacune commence par un nom et un participe à l’ablatif : c’est un ablatif absolu, qu’il faudra traduire sans mot à mot.","documents":[{"id":"phrases","type":"texte","genre":"recit","titre":"Deux phrases d’un récit de guerre","auteur":"Phrases écrites pour l’exercice","blocs":["Urbe capta, consul Romam rediit.","Hostibus victis, milites domum redierunt."],"source":"Vocabulaire : urbs = ville ; Romam = à Rome ; rediit = il revint ; hostes = ennemis ; milites = soldats ; domum = chez eux ; redierunt = ils revinrent."},{"id":"part","type":"tableau","titre":"Les participes","colonnes":["Participe","Finale","Exemple","Sens"],"lignes":[["Présent actif","-ns, -ntis","amans","aimant"],["Parfait passif","-tus, -a, -um","amatus","ayant été aimé"],["Futur actif","-turus","amaturus","devant aimer"],["Adjectif verbal","-ndus","amandus","qui doit être aimé"]]}],"questions":[{"enonce":"Dans la phrase 1, touche les deux mots de l’ablatif absolu.","aide":"L’ablatif absolu est un nom et un participe, sans lien grammatical avec la principale.","type":"zone","document":"phrases","multiple":true},{"enonce":"Comment traduire naturellement « Hostibus victis » dans la phrase 2 ?","aide":"L’ablatif absolu devient un complément circonstanciel de temps.","type":"choix","options":[{"id":"a","texte":"Pour vaincre les ennemis"},{"id":"b","texte":"Contre les ennemis vaincus"},{"id":"c","texte":"Les ennemis vainqueurs"},{"id":"d","texte":"Une fois les ennemis vaincus"}],"multiple":false},{"enonce":"Touche, dans le tableau, la forme qui signifie « devant aimer ».","aide":"Cherche la ligne du futur actif.","type":"zone","document":"part","multiple":false},{"enonce":"Voici des participes d’autres verbes. Classe-les d’après leur finale.","aide":"Cherche -ns, -tus ou -turus.","type":"categories","categories":[{"id":"c0","texte":"Présent actif"},{"id":"c1","texte":"Parfait passif"},{"id":"c2","texte":"Futur actif"}],"items":[{"id":"i0","texte":"monens"},{"id":"i1","texte":"docturus"},{"id":"i2","texte":"monitus"},{"id":"i3","texte":"doctus"},{"id":"i4","texte":"moniturus"},{"id":"i5","texte":"docens"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0","m1"]},"explication":"**Urbe capta** est l’ablatif absolu : « la ville ayant été prise », c’est-à-dire « après la prise de la ville »."},{"cle":{"type":"choix","ids":["d"]},"explication":"**Une fois les ennemis vaincus** : le français rend l’ablatif absolu par une circonstancielle, jamais mot à mot."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"**Amaturus** est le participe futur actif : « devant aimer »."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c1","i3":"c1","i4":"c2","i5":"c0"}},"explication":"Les finales sont les mêmes que dans le tableau : **-ns** (présent), **-tus** (parfait passif), **-turus** (futur)."}]$ex$::jsonb),
