   $ex${"titre":"Delenda est Carthago","competence":"analyser-texte","situation":"Rome, IIe siècle av. J.-C. : Caton l’Ancien terminait ses discours par une formule restée célèbre. Tu analyses ses deux versions, puis tu situes la ville visée.","documents":[{"id":"caton","type":"texte","genre":"source","titre":"La formule de Caton","blocs":["Carthago delenda est.","Ceterum censeo Carthaginem esse delendam."],"source":"Formules attribuées à Caton l’Ancien (IIe siècle av. J.-C.). Vocabulaire : ceterum = du reste ; censeo = je pense ; esse = être."},{"id":"carte","type":"carte","titre":"Deux villes de la Méditerranée","fond":"mediterranee","cadrage":[-2,31,22,46],"lieux":[{"id":"z1","lieu":"rome","symbole":"lettre","lettre":"A","teinte":"violet"},{"id":"z2","lieu":"carthage","symbole":"lettre","lettre":"B","teinte":"violet"}],"source":"Carte écrite pour l’exercice"}],"questions":[{"enonce":"Dans la deuxième phrase, touche le verbe d’opinion qui introduit la proposition infinitive.","aide":"Il signifie « je pense ».","type":"zone","document":"caton","multiple":false},{"enonce":"Touche le sujet de la proposition infinitive « esse delendam ».","aide":"Dans une infinitive, le sujet est à l’accusatif.","type":"zone","document":"caton","multiple":false},{"enonce":"Quelle est la traduction de « Carthago delenda est » ?","aide":"L’adjectif verbal en -ndus exprime l’obligation.","type":"choix","options":[{"id":"a","texte":"Carthage va détruire Rome."},{"id":"b","texte":"Carthage doit être détruite."},{"id":"c","texte":"Carthage a été détruite."},{"id":"d","texte":"Carthage détruit la ville."}],"multiple":false},{"enonce":"Complète la traduction de la deuxième phrase.","aide":"C’est la même idée d’obligation que dans la première formule.","type":"trous","segments":["Du reste, je pense que Carthage ",0," être ",1,"."],"banque":["détruire","détruite","doit","peut","a été"]},{"enonce":"Caton veut voir cette ville détruite. Touche sa lettre sur la carte.","aide":"Carthage se trouve en Afrique du Nord, face à la Sicile.","type":"zone","document":"carte","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4"]},"explication":"**Censeo** (« je pense ») est le verbe d’opinion : après lui, le latin met une proposition infinitive."},{"cle":{"type":"zone","ids":["m5"]},"explication":"**Carthaginem** est le sujet de l’infinitive : il est à l’accusatif."},{"cle":{"type":"choix","ids":["b"]},"explication":"**Carthage doit être détruite** : *delenda* est un adjectif verbal, qui exprime l’obligation."},{"cle":{"type":"trous","trous":[["doit"],["detruite"]]},"affichage":"doit · détruite","explication":"La phrase signifie : du reste, je pense que Carthage **doit** être **détruite**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Carthage (B) est en Afrique du Nord, à l’emplacement de l’actuelle Tunisie ; la lettre A marque Rome."}]$ex$::jsonb),
