   $ex${"titre":"La République, restaurée ou récupérée ?","competence":"analyser-document","situation":"Vers 20 av. J.-C., Lucius écrit à son frère. Il lui raconte ce qu’Auguste a changé à Rome, et se demande ce qui reste de la République.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre de Lucius à son frère","auteur":"Lettre imaginée pour l’exercice","blocs":["Cher Marcus, les consuls sont élus comme avant, le Sénat se réunit, les comices votent. Pourtant, rien ne se décide sans Auguste. Il répète partout *res publica restituta*, « la République restaurée ». Je me demande s’il la restaure vraiment ou s’il n’en garde que le nom. Lucius"]},{"id":"frise","type":"frise","titre":"De César à Auguste","debut":-60,"fin":-20,"pas":5,"evenements":[{"id":"z1","date":-44,"nom":"Ides de mars"},{"id":"z2","date":-27,"nom":"Principat d’Auguste"}]}],"questions":[{"enonce":"Touche le mot dont Auguste affirme la restauration.","aide":"C’est le mot qui suit « restaurée » dans la formule.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche l’événement qui marque la naissance du pouvoir d’Auguste.","aide":"Le principat est fondé en 27 av. J.-C.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’assassinat de César (ides de mars) de la fondation du principat ?","aide":"Soustrais les deux dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Que laisse entendre Lucius dans sa lettre ?","aide":"Lucius cite les institutions, puis dit « pourtant ».","type":"choix","options":[{"id":"a","texte":"Les consuls et le Sénat ont été supprimés par Auguste lui-même"},{"id":"b","texte":"Les comices ont obtenu un pouvoir plus grand qu’avant son arrivée"},{"id":"c","texte":"La République a été entièrement rétablie et rend le pouvoir au peuple"},{"id":"d","texte":"Les institutions existent encore, mais le vrai pouvoir est à Auguste"}],"multiple":false}]}$ex$::jsonb,
