,"texte":"Gaius"},{"id":"g2","texte":"Sôsias"},{"id":"g3","texte":"Livia"}],"droite":[{"id":"d0","texte":"cliens : il soutient"},{"id":"d1","texte":"servus : il n’est pas libre"},{"id":"d2","texte":"patronus : il protège"},{"id":"d3","texte":"materfamilias : respectée, sans droits politiques"}]},{"enonce":"Classe chaque personnage selon ses droits politiques.","aide":"Le citoyen homme vote ; l’esclave et la femme ne votent pas.","type":"categories","categories":[{"id":"c0","texte":"Droits politiques"},{"id":"c1","texte":"Aucun droit politique"}],"items":[{"id":"i0","texte":"Gaius, artisan citoyen"},{"id":"i1","texte":"Titus, sénateur"},{"id":"i2","texte":"Livia, la materfamilias"},{"id":"i3","texte":"Sôsias, esclave"}]},{"enonce":"Pourquoi les clients sont-ils précieux pour un sénateur qui veut faire carrière ?","aide":"Pense aux comices, qui élisent les magistrats.","type":"choix","options":[{"id":"a","texte":"Ils paient à sa place les impôts de toute la cité"},{"id":"b","texte":"Ils votent pour lui et pour ses proches aux élections"},{"id":"c","texte":"Ils siègent à sa place au Sénat pendant ses absences"},{"id":"d","texte":"Ils commandent à sa place les armées de la République"}],"multiple":false}]}$ex$::jsonb,
