:"g2","texte":"|x − 10| ≤ 0,5"},{"id":"g3","texte":"|x| ≤ 4"}],"droite":[{"id":"d0","texte":"[−4 ; 2]"},{"id":"d1","texte":"[9,5 ; 10,5]"},{"id":"d2","texte":"[−4 ; 4]"},{"id":"d3","texte":"[−3 ; 7]"}]}]}$ex$::jsonb,
