   $ex$[{"cle":{"type":"zone","ids":["r0c0","r2c0"]},"explication":"1/4 = 25/100 et 3/8 = 375/1000 sont décimaux. Les dénominateurs 3 et 7 ne sont pas des produits de 2 et de 5 : 1/3, 2/3 et 1/7 ne sont **pas** décimaux."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"Le bloc **142857** compte **6** chiffres : l’écriture est infinie mais périodique."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est un quotient d’entiers, donc **rationnel** ; son écriture 0,333… est infinie, donc il n’est **pas décimal**."}]$ex$::jsonb),
