  ('7aaec3ed-c892-51f4-9408-c6383039372a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La dalle carrée et la diagonale impossible","competence":"raisonner","situation":"Un artisan pose une dalle carrée de côté 1 m. Il veut calculer la longueur d de sa diagonale. Son apprenti affirme que d s’écrit comme une fraction : l’artisan lui montre pourquoi c’est impossible.","documents":[{"id":"dalle","type":"figure","titre":"La dalle (hors échelle)","cadre":{"xmin":0,"xmax":8,"ymin":0,"ymax":8},"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":7,"y":1,"position":"se"},{"id":"C","x":7,"y":7,"position":"ne"},{"id":"D","x":1,"y":7,"position":"no"}],"segments":[{"de":"A","a":"B","codage":1,"longueur":"1 m"},{"de":"B","a":"C","codage":1,"longueur":"1 m"},{"de":"C","a":"D","codage":1},{"de":"D","a":"A","codage":1},{"de":"A","a":"C","style":"pointilles","teinte":"corail","longueur":"d"}],"angles":[{"sommet":"B","de":"A","a":"C","droit":true}],"source":"Figure hors échelle"},{"id":"liste","type":"tableau","titre":"Six nombres à trier","colonnes":["Lettre","Nombre"],"lignes":[["a","√4"],["b","√5"],["c","π"],["d","0,25"],["e","√(9/4)"],["f","22/7"]],"enteteLignes":true,"source":"Nombres choisis pour l’exercice"}],"questions":[{"enonce":"Dans le triangle ABC rectangle en B, applique Pythagore. Que vaut d² ?","aide":"AC² = AB² + BC², avec AB = BC = 1.","type":"nombre"},{"enonce":"Remets dans l’ordre la démonstration par l’absurde que √2 n’est pas une fraction.","aide":"On part de l’hypothèse, on calcule, puis on tombe sur une impossibilité.","type":"ordre","items":[{"id":"a","texte":"On écrit p = 2k, d’où q² = 2k²"},{"id":"b","texte":"On suppose √2 = p/q, avec p/q irréductible"},{"id":"c","texte":"q est pair aussi : p et q ont 2 en facteur commun, contradiction"},{"id":"d","texte":"On élève au carré : 2q² = p²"},{"id":"e","texte":"p² est pair, donc p est pair"}]},{"enonce":"Touche les nombres irrationnels de la liste.","aide":"Simplifie ce qui peut l’être : √4, √(9/4), et rappelle-toi que 22/7 est un quotient d’entiers.","type":"zone","document":"liste","multiple":true},{"enonce":"Écris √8 + √2 sous la forme a√2. Que vaut a ?","aide":"Écris √8 = √4 × √2.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"d² = 1² + 1² = **2** : d est donc le nombre positif dont le carré vaut 2, c’est √2."},{"cle":{"type":"ordre","ids":["b","d","e","a","c"]},"explication":"On suppose le contraire, on en déduit que p **et** q sont pairs, ce qui contredit l’irréductibilité : **√2 est irrationnel**."},{"cle":{"type":"zone","ids":["r1c1","r2c1"]},"explication":"√4 = 2, √(9/4) = 3/2, 0,25 = 1/4 et 22/7 sont des rationnels. Seuls **√5** et **π** sont irrationnels (22/7 n’est qu’une valeur approchée de π)."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"√8 = 2√2, donc √8 + √2 = 2√2 + √2 = **3√2** : a = 3."}]$ex$::jsonb),
