  ('7a85fcba-5f8b-5eb6-aabf-5bcc73b851ca'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les calculs d’Hugo passés au test","competence":"raisonner","situation":"Hugo a recopié trois égalités de son cahier. Sa prof lui conseille un réflexe de contrôle : remplacer x par 1 dans chaque membre et comparer. Si les deux valeurs diffèrent, l’égalité est fausse.","documents":[{"id":"hugo","type":"tableau","titre":"Le test x = 1","colonnes":["Calcul d’Hugo","Gauche (x = 1)","Droite (x = 1)"],"lignes":[["(x + 2)² = x² + 4","?","5"],["(x² − 4)/(x − 2) = x + 2","3","3"],["(x + 3)/(x + 5) = 3/5","2/3","3/5"]],"enteteLignes":false,"source":"Calculs écrits pour l’exercice"},{"id":"puiss","type":"texte","genre":"consigne","titre":"La dernière ligne de son cahier","blocs":["Hugo a aussi écrit : (a³)² × a⁻⁴ = a⁻²","Il pense avoir multiplié les exposants puis les avoir ajoutés."],"source":"Texte écrit pour l’exercice"}],"questions":[{"enonce":"Calcule la valeur du membre de gauche (x + 2)² pour x = 1 (case « ? »).","aide":"Remplace x par 1, additionne, puis élève au carré.","type":"nombre"},{"enonce":"Touche les calculs qui sont faux d’après le test.","aide":"Compare les deux valeurs de chaque ligne : sont-elles égales ?","type":"zone","document":"hugo","multiple":true},{"enonce":"Pour (x² − 4)/(x − 2), quelle valeur de x est interdite ?","aide":"Un quotient n’existe pas quand le dénominateur est nul.","type":"nombre"},{"enonce":"Rends rationnel le dénominateur de 1/√5 : multiplie le haut et le bas par √5.","aide":"Au dénominateur, √5 × √5 = 5.","type":"trous","segments":["1/√5 = √5 / ",0]},{"enonce":"Quel est l’exposant correct de a dans (a³)² × a⁻⁴ ?","aide":"(a³)² = a⁶ ; ensuite on ajoute les exposants : 6 + (−4).","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9","explication":"(1 + 2)² = 3² = **9**, alors que le membre de droite vaut 1² + 4 = 5 : l’égalité est fausse."},{"cle":{"type":"zone","ids":["r0c0","r2c0"]},"explication":"Ligne 1 : 9 ≠ 5 ; ligne 3 : 2/3 ≠ 3/5. En revanche la ligne 2 donne 3 = 3 : l’égalité est vraie (pour x ≠ 2)."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"x − 2 = 0 donne x = **2** : c’est la valeur interdite. Pour x ≠ 2, (x − 2)(x + 2)/(x − 2) = x + 2."},{"cle":{"type":"trous","trous":[["5"]]},"affichage":"5","explication":"1/√5 = (1 × √5)/(√5 × √5) = **√5/5**."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"(a³)² = a⁶, puis a⁶ × a⁻⁴ = a⁶⁻⁴ = **a²** : l’exposant est 2, et non −2."}]$ex$::jsonb),
  ('d513d5d5-e95d-5b04-b628-b4a1970f42bb'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les calculs de tête de Sacha","competence":"calculer","situation":"Sacha adore calculer de tête : il décompose les nombres pour utiliser une identité remarquable. Il a collé les trois formules sur un panneau de sa chambre.","documents":[{"id":"panneau","type":"fiche","modele":"panneau","entete":"Les trois identités","sousTitre":"a et b sont deux nombres quelconques","emoji":"🧮","lignes":[{"texte":"Identité 1","valeur":"(a + b)² = a² + 2ab + b²","id":"z1"},{"texte":"Identité 2","valeur":"(a − b)² = a² − 2ab + b²","id":"z2"},{"texte":"Identité 3","valeur":"(a + b)(a − b) = a² − b²","id":"z3"}],"pied":"Panneau imaginé pour l’exercice","teinte":"violet"}],"questions":[{"enonce":"Pour calculer 103 × 97 de tête, touche l’identité que Sacha utilise.","aide":"Écris 103 = 100 + 3 et 97 = 100 − 3 : quelle forme de produit obtiens-tu ?","type":"zone","document":"panneau","multiple":false},{"enonce":"Calcule 103 × 97.","aide":"Applique a² − b² avec a = 100 et b = 3.","type":"nombre"},{"enonce":"Pour 51², Sacha écrit 51 = 50 + 1. Complète.","aide":"Identité 1 : le double produit est 2 × 50 × 1.","type":"trous","segments":["51² = (50 + ",0,")² = 2 500 + ",1," + 1 = ",2]},{"enonce":"Calcule 29² en écrivant 29 = 30 − 1.","aide":"Identité 2 : a² − 2ab + b² avec a = 30 et b = 1.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"103 × 97 = (100 + 3)(100 − 3) : c’est la forme **(a + b)(a − b)** de l’identité 3."},{"cle":{"type":"nombre","valeur":9991,"tolerance":0},"affichage":"9991","explication":"103 × 97 = 100² − 3² = 10 000 − 9 = **9 991**."},{"cle":{"type":"trous","trous":[["1"],["100"],["2601","2 601"]]},"affichage":"1 · 100 · 2601","explication":"51² = (50 + 1)² = 50² + 2 × 50 × 1 + 1² = 2 500 + **100** + 1 = **2 601**."},{"cle":{"type":"nombre","valeur":841,"tolerance":0},"affichage":"841","explication":"29² = 30² − 2 × 30 × 1 + 1² = 900 − 60 + 1 = **841**."}]$ex$::jsonb),
