  ('d513d5d5-e95d-5b04-b628-b4a1970f42bb'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le coffre à deux serrures","competence":"resoudre","situation":"Dans un jeu d’évasion, un coffre s’ouvre avec le nombre positif x qui vérifie l’équation (2x + 1)² − 9 = 0. Un indice rappelle le nombre de solutions de trois équations voisines : il faut ne pas les confondre.","documents":[{"id":"enigme","type":"texte","genre":"consigne","titre":"L’énigme du coffre","blocs":["(2x + 1)² − 9 = 0","Le code est la solution positive de cette équation."],"source":"Énigme écrite pour l’exercice"},{"id":"trois","type":"tableau","titre":"Trois équations voisines","colonnes":["N°","Équation"],"lignes":[["E1","x² − 49 = 0"],["E2","x² + 14x + 49 = 0"],["E3","x² + 49 = 0"]],"enteteLignes":false,"source":"Équations choisies pour l’exercice"}],"questions":[{"enonce":"Remets dans l’ordre les étapes de résolution de (2x + 1)² − 9 = 0.","aide":"Factorise avant de résoudre : on reconnaît d’abord la forme a² − b².","type":"ordre","items":[{"id":"a","texte":"On résout 2x − 2 = 0 ou 2x + 4 = 0"},{"id":"b","texte":"On reconnaît a² − b² avec a = 2x + 1 et b = 3"},{"id":"c","texte":"Un produit est nul si l’un de ses facteurs est nul"},{"id":"d","texte":"On simplifie : (2x − 2)(2x + 4) = 0"},{"id":"e","texte":"On factorise : (2x + 1 − 3)(2x + 1 + 3) = 0"}]},{"enonce":"Vérifie la factorisation : (2x + 1)² − 9 = (2x − 2)(2x + ___).","aide":"Calcule 2x + 1 + 3.","type":"trous","segments":["(2x − 2)(2x + ",0,") = 0"]},{"enonce":"Quel est le code du coffre (la solution positive) ?","aide":"Résous 2x − 2 = 0.","type":"nombre"},{"enonce":"Quelle est l’autre solution de l’équation (la solution négative) ?","aide":"Résous 2x + 4 = 0.","type":"nombre"},{"enonce":"Associe chaque équation du tableau à son nombre de solutions réelles.","aide":"Factorise E1 et E2 ; pour E3, un carré peut-il être égal à −49 ?","type":"association","gauche":[{"id":"g0","texte":"E1 : x² − 49 = 0"},{"id":"g1","texte":"E2 : x² + 14x + 49 = 0"},{"id":"g2","texte":"E3 : x² + 49 = 0"}],"droite":[{"id":"d0","texte":"1 solution"},{"id":"d1","texte":"Aucune solution"},{"id":"d2","texte":"2 solutions"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"ordre","ids":["b","e","d","c","a"]},"explication":"On factorise avec **a² − b² = (a − b)(a + b)**, puis on utilise la règle du produit nul."},{"cle":{"type":"trous","trous":[["4"]]},"affichage":"4","explication":"(2x + 1 − 3)(2x + 1 + 3) = (2x − 2)(2x + **4**)."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1","explication":"2x − 2 = 0 donne x = **1**. L’autre facteur 2x + 4 = 0 donne x = −2, qui n’est pas positif."},{"cle":{"type":"nombre","valeur":-2,"tolerance":0},"affichage":"−2","explication":"2x + 4 = 0 donne 2x = −4, soit x = **−2**. S = {−2 ; 1}."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"E1 = (x − 7)(x + 7) donne ±7 : **2 solutions**. E2 = (x + 7)² ne s’annule qu’en −7 : **1 solution**. E3 : x² = −49 est impossible : **aucune**."}]$ex$::jsonb),
  ('ae2a882f-7b8b-53bb-80bf-21b8b4812122'::uuid, 1, 1, 5, 20, 4,
