  ('ae2a882f-7b8b-53bb-80bf-21b8b4812122'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le four qui refroidit","competence":"resoudre","situation":"Après la cuisson, la température d’un four est donnée par T(t) = 220 − 12t (en °C), où t est le temps écoulé en minutes. Élodie a relevé quelques valeurs. Elle peut sortir ses gâteaux dès que T ≤ 100 °C.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Température du four","categories":["0","2","4","6","8","10","12"],"series":[{"nom":"Température","valeurs":[220,196,172,148,124,100,76],"teinte":"corail"}],"axeY":{"titre":"Température","unite":"°C","min":60,"max":240,"pas":20},"axeX":{"titre":"Temps écoulé (min)"},"valeurs":false,"source":"T(t) = 220 − 12t, valeurs calculées"}],"questions":[{"enonce":"Lis le graphique : quelle est la température au bout de 6 minutes ?","aide":"Cherche la graduation 6 sur l’axe du temps, puis monte jusqu’au point.","type":"nombre","unite":"°C"},{"enonce":"Touche le point où le four atteint 100 °C.","aide":"Cherche l’ordonnée 100 sur la courbe.","type":"zone","document":"courbe","multiple":false},{"enonce":"Résous 220 − 12t ≤ 100. Au bout de combien de minutes au minimum Élodie peut-elle sortir ses gâteaux ?","aide":"Soustrais 220 aux deux membres, puis divise par −12 : le sens de l’inégalité change.","type":"nombre","unite":"min"},{"enonce":"Élodie divise −12t ≤ −120 par −12 et écrit t ≤ 10. Quelle est son erreur ?","aide":"Le graphique le montre : à t = 4, le four est-il à 100 °C ou moins ?","type":"choix","options":[{"id":"a","texte":"Il n’y a aucune erreur dans sa résolution"},{"id":"b","texte":"Elle aurait dû multiplier par 12 au lieu de diviser"},{"id":"c","texte":"Elle a oublié d’ajouter 220 de chaque côté"},{"id":"d","texte":"Elle n’a pas changé le sens de l’inégalité"}],"multiple":false}]}$ex$::jsonb,
