  ('ae2a882f-7b8b-53bb-80bf-21b8b4812122'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le bonus de vitesse","competence":"raisonner","situation":"Dans un jeu vidéo, le bonus de vitesse d’un joueur est donné par B(x) = (x − 1)/(x + 4), où x est le nombre de niveaux franchis. Le bonus n’est débloqué que lorsque B(x) ≥ 0. Mathis résout l’inéquation avec un tableau de signes.","documents":[{"id":"signes","type":"tableau","titre":"Tableau de signes de (x − 1)/(x + 4)","colonnes":["x","]−∞ ; −4[","−4","]−4 ; 1[","1","]1 ; +∞["],"lignes":[["x + 4","−","0","+","+","+"],["x − 1","−","−","−","0","+"],["(x − 1)/(x + 4)","+","||","−","0","+"]],"enteteLignes":true,"source":"Tableau construit pour l’exercice"},{"id":"tests","type":"droite","titre":"Cinq valeurs testées par Mathis","min":-6,"max":4,"pas":1,"points":[{"id":"z1","valeur":-5,"nom":"P"},{"id":"z2","valeur":-2,"nom":"Q"},{"id":"z3","valeur":0,"nom":"R"},{"id":"z4","valeur":1,"nom":"S"},{"id":"z5","valeur":3,"nom":"T"}],"source":"Valeurs choisies pour l’exercice"}],"questions":[{"enonce":"Quelle valeur de x est interdite dans le quotient (x − 1)/(x + 4) ? (c’est la double barre du tableau)","aide":"Un quotient n’existe pas quand son dénominateur est nul.","type":"nombre"},{"enonce":"Touche les cases du tableau où le quotient est strictement positif.","aide":"Regarde la dernière ligne et cherche le signe « + ».","type":"zone","document":"signes","multiple":true},{"enonce":"Touche les valeurs testées qui débloquent le bonus (B(x) ≥ 0).","aide":"Place chaque valeur dans la ligne du quotient du tableau, sans oublier que 1 annule le quotient.","type":"zone","document":"tests","multiple":true},{"enonce":"Complète l’ensemble des solutions de (x − 1)/(x + 4) ≥ 0.","aide":"Le crochet en −4 est ouvert (valeur interdite) ; en 1 le quotient vaut 0, ce qui convient pour « ≥ ».","type":"trous","segments":["S = ]−∞ ; ",0,"[ ∪ [",1," ; +∞["],"banque":["−4","−1","4","1"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":-4,"tolerance":0},"affichage":"−4","explication":"x + 4 = 0 donne x = **−4** : le quotient n’existe pas, on met une double barre."},{"cle":{"type":"zone","ids":["r2c1","r2c5"]},"explication":"Sur ]−∞ ; −4[ les deux facteurs sont négatifs : quotient **positif**. Sur ]1 ; +∞[ ils sont positifs : quotient **positif**. Entre −4 et 1, il est négatif."},{"cle":{"type":"zone","ids":["z1","z4","z5"]},"explication":"P = −5 est dans ]−∞ ; −4[ (+) ; S = 1 annule le quotient (0, donc ≥ 0 est vrai) ; T = 3 est dans ]1 ; +∞[ (+). Q = −2 et R = 0 sont entre −4 et 1 : négatif."},{"cle":{"type":"trous","trous":[["4"],["1"]]},"affichage":"−4 · 1","explication":"On garde les intervalles « + » et le 0 : −4 est **exclu** (valeur interdite), 1 est **inclus**. S = **]−∞ ; −4[ ∪ [1 ; +∞[**."}]$ex$::jsonb),
  ('ebf88cac-fd60-5a8a-aa2d-6da9a219314a'::uuid, 1, 1, 5, 20, 3,
