  ('ebf88cac-fd60-5a8a-aa2d-6da9a219314a'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le chemin le plus court vers la route","competence":"raisonner","situation":"Un terrain triangulaire ABC est bordé par une route le long du côté [BC]. On a mesuré AB = 9 m, AC = 12 m et BC = 15 m. Le propriétaire veut tracer le chemin le plus court entre le sommet A et la route.","documents":[{"id":"terrain","type":"figure","titre":"Le terrain (hors échelle)","cadre":{"xmin":0,"xmax":12,"ymin":0,"ymax":10},"points":[{"id":"A","x":2,"y":2,"position":"so"},{"id":"B","x":2,"y":8,"position":"no"},{"id":"C","x":10,"y":2,"position":"se"},{"id":"H","x":4.88,"y":5.84,"position":"ne"}],"segments":[{"de":"A","a":"B","longueur":"9 m"},{"de":"A","a":"C","longueur":"12 m"},{"id":"z1","de":"B","a":"C","longueur":"15 m"},{"id":"z2","de":"A","a":"H","style":"pointilles"}],"angles":[{"sommet":"H","de":"A","a":"C","droit":true}],"source":"Plan schématique, hors échelle"}],"questions":[{"enonce":"Calcule AB² + AC².","aide":"Élève chaque longueur au carré : 9² = 81.","type":"nombre"},{"enonce":"Que peut-on conclure du calcul précédent ?","aide":"Quel est le plus grand côté ? L’angle droit est en face de lui.","type":"choix","options":[{"id":"a","texte":"Pas rectangle (réciproque de Pythagore)"},{"id":"b","texte":"Rectangle en A (réciproque de Pythagore)"},{"id":"c","texte":"Rectangle en C (réciproque de Pythagore)"},{"id":"d","texte":"Rectangle en B (réciproque de Pythagore)"}],"multiple":false},{"enonce":"Touche le segment qui représente la distance de A à la route (BC).","aide":"La distance d’un point à une droite se mesure par la perpendiculaire.","type":"zone","document":"terrain","multiple":false},{"enonce":"Calcule l’aire du triangle ABC, rectangle en A.","aide":"Aire = (AB × AC) ÷ 2.","type":"nombre","unite":"m²"},{"enonce":"Sachant que l’aire vaut aussi (BC × AH) ÷ 2, calcule AH.","aide":"Résous 15 × AH ÷ 2 = 54.","type":"nombre","unite":"m"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":225,"tolerance":0},"affichage":"225","explication":"AB² + AC² = 81 + 144 = **225**, et BC² = 15² = 225 : les deux sont égaux."},{"cle":{"type":"choix","ids":["b"]},"explication":"BC² = AB² + AC² : par la **réciproque de Pythagore**, le triangle est rectangle en **A**, sommet opposé au plus grand côté [BC]."},{"cle":{"type":"zone","ids":["z2"]},"explication":"H est le projeté orthogonal de A sur (BC) : la distance de A à (BC) est la longueur **AH**, la plus courte de A à la route."},{"cle":{"type":"nombre","valeur":54,"tolerance":0},"affichage":"54 m²","explication":"(9 × 12) ÷ 2 = 108 ÷ 2 = **54 m²**."},{"cle":{"type":"nombre","valeur":7.2,"tolerance":0},"affichage":"7,2 m","explication":"15 × AH = 108, donc AH = 108 ÷ 15 = **7,2 m**."}]$ex$::jsonb),
  ('ebf88cac-fd60-5a8a-aa2d-6da9a219314a'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le projecteur de la scène triangulaire","competence":"geometrie","situation":"Une scène de spectacle a la forme d’un triangle ABC. Le régisseur doit placer le projecteur à l’endroit où se coupent les trois médianes, et choisir d’autres points particuliers pour le micro, la lampe et le pied de caméra.","documents":[{"id":"scene","type":"figure","titre":"La scène (1 carreau = 1 m)","cadre":{"xmin":0,"xmax":10,"ymin":0,"ymax":8},"quadrillage":true,"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":9,"y":1,"position":"se"},{"id":"C","x":5,"y":7,"position":"n"},{"id":"I","x":7,"y":4,"position":"e"},{"id":"J","x":3,"y":4,"position":"o"},{"id":"K","x":5,"y":1,"position":"s"},{"id":"G","x":5,"y":3,"position":"o"}],"segments":[{"de":"A","a":"B"},{"de":"B","a":"C"},{"de":"C","a":"A"},{"de":"A","a":"I","teinte":"violet","style":"pointilles"},{"de":"B","a":"J","teinte":"violet","style":"pointilles"},{"de":"C","a":"K","teinte":"violet","style":"pointilles","longueur":"6 m"}],"source":"I, J et K sont les milieux de [BC], [AC] et [AB]"},{"id":"cahier","type":"fiche","modele":"affiche","entete":"Cahier des charges","sousTitre":"Où poser quoi ?","emoji":"🎭","lignes":[{"texte":"Projecteur : au croisement des trois médianes"},{"texte":"Micro : à égale distance des trois sommets"},{"texte":"Lampe : à égale distance des trois côtés"},{"texte":"Caméra : au croisement des trois hauteurs"}],"pied":"Document imaginé pour l’exercice","teinte":"ambre"}],"questions":[{"enonce":"Touche l’endroit où se croisent les trois médianes : le centre de gravité.","aide":"Une médiane relie un sommet au milieu du côté opposé : cherche le point commun aux trois traits en pointillés.","type":"zone","document":"scene","multiple":false},{"enonce":"La médiane [CK] mesure 6 m. Le centre de gravité est aux deux tiers de la médiane depuis le sommet : quelle est la longueur CG ?","aide":"Calcule les deux tiers de 6.","type":"nombre","unite":"m"},{"enonce":"Quelle est alors la longueur GK ?","aide":"GK = CK − CG.","type":"nombre","unite":"m"},{"enonce":"Associe chaque point du cahier des charges au point remarquable du triangle correspondant.","aide":"Les médiatrices donnent le cercle circonscrit, les bissectrices le cercle inscrit.","type":"association","gauche":[{"id":"g0","texte":"Le projecteur : croisement des médianes"},{"id":"g1","texte":"Le micro : équidistant des sommets"},{"id":"g2","texte":"La lampe : équidistante des côtés"},{"id":"g3","texte":"La caméra : croisement des hauteurs"}],"droite":[{"id":"d0","texte":"Centre du cercle circonscrit"},{"id":"d1","texte":"Centre du cercle inscrit"},{"id":"d2","texte":"Orthocentre"},{"id":"d3","texte":"Centre de gravité"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["G"]},"explication":"Les médianes [AI], [BJ] et [CK] se coupent en **G** : c’est le centre de gravité du triangle."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 m","explication":"CG = (2/3) × 6 = **4 m**. Sur le plan, G est bien à 4 carreaux de C."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 m","explication":"GK = 6 − 4 = **2 m** : G est à un tiers de la médiane depuis le milieu K."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Médianes → **centre de gravité** ; médiatrices (équidistant des sommets) → **centre du cercle circonscrit** ; bissectrices (équidistant des côtés) → **centre du cercle inscrit** ; hauteurs → **orthocentre**."}]$ex$::jsonb),
  ('27b703e8-ce8e-5098-8991-6c9faf1c90cc'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les deux grues du chantier","competence":"geometrie","situation":"Sur un chantier, une grue déplace une caisse du point A au point B. Une seconde grue fait exactement le même déplacement, mais en partant du point C : elle dépose la caisse en D.","documents":[{"id":"grues","type":"figure","titre":"Le plan du chantier (1 carreau = 1 m)","cadre":{"xmin":0,"xmax":8,"ymin":0,"ymax":7},"quadrillage":true,"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":4,"y":2,"position":"se"},{"id":"C","x":2,"y":4,"position":"no"},{"id":"D","x":5,"y":5,"position":"ne"}],"segments":[{"id":"z1","de":"A","a":"B","teinte":"violet"},{"id":"z2","de":"C","a":"D","teinte":"turquoise"},{"id":"z3","de":"A","a":"C","style":"pointilles"},{"id":"z4","de":"B","a":"D","style":"pointilles"}],"source":"Plan schématique"}],"questions":[{"enonce":"Touche le segment qui représente le même déplacement que celui de A vers B (le vecteur AB).","aide":"Même direction, même sens, même longueur : cherche le segment parallèle à [AB] qui part de C.","type":"zone","document":"grues","multiple":false},{"enonce":"De combien de carreaux vers la droite le vecteur AB déplace-t-il la caisse ?","aide":"Compte les carreaux entre l’abscisse de A et celle de B.","type":"nombre","unite":"carreaux"},{"enonce":"Complète l’égalité des deux vecteurs.","aide":"Cherche le vecteur qui part de C pour arriver en D.","type":"trous","segments":["AB = ",0],"banque":["BD","AC","DC","CD"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le déplacement de C vers D est le même que de A vers B : **CD = AB**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 carreaux","explication":"A est à l’abscisse 1 et B à l’abscisse 4 : le déplacement est de 4 − 1 = **3** carreaux vers la droite."},{"cle":{"type":"trous","trous":[["cd"]]},"affichage":"CD","explication":"Les deux grues font le même déplacement : **AB = CD**. Cela signifie que ABDC est un parallélogramme."}]$ex$::jsonb),
  ('27b703e8-ce8e-5098-8991-6c9faf1c90cc'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"La tournée du livreur","competence":"raisonner","situation":"Un livreur part de la boulangerie A, passe par le collège B, puis la mairie C, et termine à la gare D. Il veut savoir à quel seul déplacement équivaut chacune de ses étapes.","documents":[{"id":"tournee","type":"figure","titre":"La tournée (1 carreau = 1 km)","cadre":{"xmin":0,"xmax":12,"ymin":0,"ymax":8},"quadrillage":true,"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":4,"y":3,"position":"no"},{"id":"C","x":8,"y":2,"position":"se"},{"id":"D","x":10,"y":6,"position":"ne"}],"segments":[{"de":"A","a":"B","teinte":"violet"},{"de":"B","a":"C","teinte":"turquoise"},{"de":"C","a":"D","teinte":"corail"}],"source":"Plan schématique"}],"questions":[{"enonce":"Le trajet AB + BC se résume à un seul déplacement qui part de A. Touche le point d’arrivée de ce déplacement.","aide":"Enchaîne les deux déplacements : on va de A à B, puis de B à…","type":"zone","document":"tournee","multiple":false},{"enonce":"Associe chaque somme à son résultat.","aide":"Pour AB − AC, écris AB + CA (l’opposé de AC) puis réordonne.","type":"association","gauche":[{"id":"g0","texte":"AB + BC + CD"},{"id":"g1","texte":"AC + CB"},{"id":"g2","texte":"AB + BA"},{"id":"g3","texte":"AB − AC"}],"droite":[{"id":"d0","texte":"AD"},{"id":"d1","texte":"AB"},{"id":"d2","texte":"CB"},{"id":"d3","texte":"le vecteur nul"}]},{"enonce":"Le trajet aller AB mesure 4 km. Quelle est la norme du vecteur −3AB ?","aide":"Multiplier par −3 change le sens, mais la norme est multipliée par |−3| = 3.","type":"nombre","unite":"km"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["C"]},"explication":"D’après la relation de Chasles, **AB + BC = AC** : le livreur arrive en **C**."},{"cle":{"type":"association","paires":{"g0":"d0","g1":"d1","g3":"d2","g2":"d3"}},"explication":"Chasles : AB + BC + CD = **AD** ; AC + CB = **AB** ; AB + BA = **0** (on revient au départ) ; AB − AC = AB + CA = CA + AB = **CB**."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 km","explication":"La norme de −3AB est |−3| × 4 = **12 km** : une norme est toujours positive, seul le sens change."}]$ex$::jsonb),
  ('27b703e8-ce8e-5098-8991-6c9faf1c90cc'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le vol du drone en parallélogramme","competence":"resoudre","situation":"Un drone décrit le parallélogramme ABCD au-dessus d’un champ, puis traverse par les diagonales [AC] et [BD]. Pour programmer ses déplacements, on exprime chaque trajet avec les vecteurs AB et AD.","documents":[{"id":"champ","type":"figure","titre":"Le champ (1 carreau = 1 m)","cadre":{"xmin":0,"xmax":10,"ymin":0,"ymax":6},"quadrillage":true,"points":[{"id":"A","x":1,"y":1,"position":"so"},{"id":"B","x":6,"y":1,"position":"se"},{"id":"C","x":8,"y":4,"position":"ne"},{"id":"D","x":3,"y":4,"position":"no"}],"segments":[{"de":"A","a":"B"},{"de":"B","a":"C"},{"de":"C","a":"D"},{"de":"D","a":"A"},{"id":"z1","de":"A","a":"C","style":"pointilles","teinte":"violet"},{"id":"z2","de":"B","a":"D","style":"pointilles","teinte":"corail"}],"source":"Plan schématique"},{"id":"deplacements","type":"tableau","titre":"Déplacements en carreaux","colonnes":["Vecteur","Vers la droite","Vers le haut"],"lignes":[["AB","5","0"],["AD","2","3"],["AC","?","?"],["BD","?","?"]],"enteteLignes":true,"source":"Valeurs lues sur le plan"}],"questions":[{"enonce":"Touche la diagonale qui représente la somme AB + AD (règle du parallélogramme).","aide":"Pour deux vecteurs de même origine A, la somme est la diagonale issue de A.","type":"zone","document":"champ","multiple":false},{"enonce":"Complète pour exprimer BD avec AB et AD (relation de Chasles).","aide":"Pour aller de B à D, on peut passer par A.","type":"trous","segments":["BD = ",0," + ",1],"banque":["AB","BA","DA","AD"]},{"enonce":"Dans le tableau, complète la case « vers la droite » de AC = AB + AD.","aide":"Additionne les déplacements vers la droite de AB et de AD.","type":"nombre"},{"enonce":"Complète maintenant la case « vers la droite » de BD = AD − AB (un nombre négatif signifie « vers la gauche »).","aide":"Soustrais : (vers la droite de AD) − (vers la droite de AB).","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"AB et AD partent du même point A : leur somme est la diagonale issue de A, **AC**."},{"cle":{"type":"trous","trous":[["ba"],["ad"]]},"affichage":"BA · AD","explication":"BD = BA + AD (Chasles) : on revient de B à A, puis on va de A à D. Comme BA = −AB, **BD = AD − AB**."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7","explication":"AC = AB + AD : vers la droite, 5 + 2 = **7** carreaux ; vers le haut, 0 + 3 = 3."},{"cle":{"type":"nombre","valeur":-3,"tolerance":0},"affichage":"−3","explication":"BD = AD − AB : 2 − 5 = **−3** vers la droite, soit 3 carreaux vers la gauche ; et 3 − 0 = 3 vers le haut."}]$ex$::jsonb),
  ('a6fc7a9d-dc23-5456-bb58-751dc2551f24'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La carte au trésor de Camille","competence":"geometrie","situation":"Camille a dessiné la carte au trésor du camp d’été dans un repère orthonormé (1 carreau = 1 m). Le départ est en P, un arbre en Q et le trésor est caché à côté du rocher R.","documents":[{"id":"carte","type":"figure","titre":"La carte au trésor","cadre":{"xmin":0,"xmax":9,"ymin":0,"ymax":7},"quadrillage":true,"axes":true,"points":[{"id":"P","x":1,"y":1,"position":"so"},{"id":"Q","x":4,"y":5,"position":"no"},{"id":"R","x":7,"y":2,"position":"se"}],"segments":[{"de":"P","a":"Q","style":"pointilles","teinte":"violet"}],"source":"Carte imaginée pour l’exercice"}],"questions":[{"enonce":"Touche le point de coordonnées (7 ; 2).","aide":"Lis d’abord l’abscisse sur l’axe horizontal, puis l’ordonnée sur l’axe vertical.","type":"zone","document":"carte","multiple":false},{"enonce":"Donne les coordonnées du vecteur PQ.","aide":"On soustrait toujours l’origine à l’extrémité : (xQ − xP ; yQ − yP).","type":"trous","segments":["PQ ( ",0," ; ",1," )"]},{"enonce":"Quelle est la distance PQ, en mètres ? (le repère est orthonormé)","aide":"Utilise √((xQ − xP)² + (yQ − yP)²).","type":"nombre","unite":"m"},{"enonce":"Camille pose une pelle au milieu de [PQ]. Quelle est l’abscisse de ce milieu ?","aide":"L’abscisse du milieu est la moyenne des deux abscisses.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["R"]},"explication":"Le point d’abscisse 7 et d’ordonnée 2 est le rocher **R**."},{"cle":{"type":"trous","trous":[["3"],["4"]]},"affichage":"3 · 4","explication":"PQ(4 − 1 ; 5 − 1) = **(3 ; 4)**."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 m","explication":"PQ = √(3² + 4²) = √25 = **5 m**."},{"cle":{"type":"nombre","valeur":2.5,"tolerance":0},"affichage":"2,5","explication":"xM = (1 + 4)/2 = **2,5**."}]$ex$::jsonb),
  ('a6fc7a9d-dc23-5456-bb58-751dc2551f24'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le podium parallélogramme","competence":"raisonner","situation":"Pour un spectacle, on a placé quatre projecteurs aux points A(−2 ; 1), B(3 ; 2), C(5 ; 5) et D(0 ; 4). Le technicien veut vérifier, avec des coordonnées, que ABCD est un parallélogramme.","documents":[{"id":"podium","type":"figure","titre":"Les quatre projecteurs","cadre":{"xmin":-3,"xmax":7,"ymin":-1,"ymax":6},"quadrillage":true,"axes":true,"points":[{"id":"A","x":-2,"y":1,"position":"so"},{"id":"B","x":3,"y":2,"position":"se"},{"id":"C","x":5,"y":5,"position":"ne"},{"id":"D","x":0,"y":4,"position":"no"}],"segments":[{"de":"A","a":"B"},{"de":"B","a":"C"},{"de":"C","a":"D"},{"de":"D","a":"A"}],"source":"Plan imaginé pour l’exercice"}],"questions":[{"enonce":"Calcule les coordonnées du vecteur AB.","aide":"On calcule (xB − xA ; yB − yA) : attention à soustraire −2.","type":"trous","segments":["AB ( ",0," ; ",1," )"]},{"enonce":"Les coordonnées de DC sont (5 − 0 ; 5 − 4) = (5 ; 1). Que peut-on conclure ?","aide":"Un quadrilatère ABCD est un parallélogramme quand AB = DC.","type":"choix","options":[{"id":"a","texte":"ABCD n’est pas un parallélogramme, car AB ≠ DC"},{"id":"b","texte":"ABCD est un parallélogramme, car AB = DC"},{"id":"c","texte":"On ne peut rien conclure"},{"id":"d","texte":"ABCD est un parallélogramme, car AB = AD"}],"multiple":false},{"enonce":"Autre méthode : quelle est l’abscisse du milieu de la diagonale [AC] ?","aide":"Moyenne des abscisses de A et de C.","type":"nombre"},{"enonce":"Quelle est l’ordonnée du milieu de la diagonale [BD] ?","aide":"Moyenne des ordonnées de B et de D.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["5"],["1"]]},"affichage":"5 · 1","explication":"AB(3 − (−2) ; 2 − 1) = **(5 ; 1)**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les vecteurs AB et DC ont les mêmes coordonnées : **AB = DC**, donc ABCD est un **parallélogramme**."},{"cle":{"type":"nombre","valeur":1.5,"tolerance":0},"affichage":"1,5","explication":"xI = (−2 + 5)/2 = 3/2 = **1,5**."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"yJ = (2 + 4)/2 = **3**. Le milieu de [BD] est (1,5 ; 3), identique à celui de [AC] : les diagonales ont le même milieu."}]$ex$::jsonb),
  ('a6fc7a9d-dc23-5456-bb58-751dc2551f24'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Les drones sont-ils alignés ?","competence":"resoudre","situation":"Lors d’un spectacle, cinq drones sont placés aux points A, B, C, D et E d’un repère orthonormé. Un sixième drone F doit se placer à l’abscisse 11 pour être aligné avec A et B. On utilise le critère de colinéarité : u(x ; y) et v(x’ ; y’) sont colinéaires si et seulement si xy’ − yx’ = 0.","documents":[{"id":"coord","type":"tableau","titre":"Coordonnées des drones","colonnes":["Drone","Abscisse","Ordonnée"],"lignes":[["A","−1","2"],["B","2","3"],["C","8","5"],["D","5","4"],["E","6","3"]],"enteteLignes":true,"source":"Positions imaginées pour l’exercice"},{"id":"ciel","type":"figure","titre":"Le ciel vu de dessus","cadre":{"xmin":-2,"xmax":10,"ymin":0,"ymax":7},"quadrillage":true,"axes":true,"points":[{"id":"A","x":-1,"y":2,"position":"so"},{"id":"B","x":2,"y":3,"position":"no"},{"id":"C","x":8,"y":5,"position":"no"},{"id":"D","x":5,"y":4,"position":"no"},{"id":"E","x":6,"y":3,"position":"se"}],"source":"Plan imaginé pour l’exercice"}],"questions":[{"enonce":"Les vecteurs AB et AC ont pour coordonnées (3 ; 1) et (9 ; 3). Calcule leur déterminant 3 × 3 − 1 × 9.","aide":"Multiplie en croix : 3 × 3 puis 1 × 9, et soustrais.","type":"nombre"},{"enonce":"Touche les drones alignés avec A et B (parmi C, D et E).","aide":"Calcule les coordonnées de AD et AE, puis leur déterminant avec AB(3 ; 1).","type":"zone","document":"ciel","multiple":true},{"enonce":"Calcule le déterminant de AB(3 ; 1) et AE(7 ; 1).","aide":"Multiplie en croix : 3 × 1 puis 1 × 7.","type":"nombre"},{"enonce":"Le drone F a pour coordonnées (11 ; t). Pour quelle valeur de t est-il aligné avec A et B ?","aide":"AF a pour coordonnées (12 ; t − 2). Écris det(AB, AF) = 0 : 3(t − 2) − 1 × 12 = 0.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":0,"tolerance":0},"affichage":"0","explication":"3 × 3 − 1 × 9 = 9 − 9 = **0** : AB et AC sont colinéaires, donc A, B, C sont alignés."},{"cle":{"type":"zone","ids":["C","D"]},"explication":"AD(6 ; 2) : 3 × 2 − 1 × 6 = 0, aligné. AE(7 ; 1) : 3 × 1 − 1 × 7 = −4 ≠ 0, **pas** aligné. Les drones alignés sont **C et D**."},{"cle":{"type":"nombre","valeur":-4,"tolerance":0},"affichage":"−4","explication":"3 × 1 − 1 × 7 = 3 − 7 = **−4**. Il est non nul : AB et AE ne sont pas colinéaires."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"3(t − 2) − 12 = 0 donne t − 2 = 4, soit t = **6**."}]$ex$::jsonb),
